import { Book } from "@/lib/types";

export const judges: Book = {
  id: "judges",
  name: "Richter",
  shortName: "Ri",
  testament: "old",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Und es geschah nach dem Tod Josuas*, da befragten die Söhne Israel den HERRN* und sagten: Wer von uns soll zuerst gegen die Kanaaniter hinaufziehen*, um gegen sie zu kämpfen*?", heading: "Nicht eroberte Gebiete in Südkanaan", footnotes: ["℘ Kap. 2,8", "℘ 2Mo 18,15; 1Sam 10,22; 1Kö 22,5", "℘ Kap. 20,18.23", "℘ 4Mo 27,21; 1Sam 10,22"] },
      { number: 2, text: "Und der HERR sprach: Juda soll hinaufziehen*. Siehe, ich habe das Land in seine Hand gegeben*.", footnotes: ["℘ Kap. 20,18", "℘ Kap. 20,28; 1Mo 49,8.9; Jos 2,24"] },
      { number: 3, text: "Und Juda sagte zu seinem Bruder Simeon: Zieh mit mir hinauf in mein Los, dass wir <gemeinsam> gegen die Kanaaniter kämpfen, dann will auch ich mit dir in dein Los ziehen! Da zog Simeon mit ihm." },
      { number: 4, text: "Und Juda zog hinauf, und der HERR gab die Kanaaniter und die Perisiter in ihre Hand; und sie schlugen sie bei Besek, zehntausend Mann." },
      { number: 5, text: "Und sie fanden den Adoni-Besek in Besek und kämpften gegen ihn. Und sie schlugen die Kanaaniter und die Perisiter*.", footnotes: ["℘ Kap. 3,5"] },
      { number: 6, text: "Und Adoni-Besek floh. Sie aber jagten ihm nach, packten ihn und hieben ihm die Daumen seiner Hände und <die großen Zehen> seiner Füße ab." },
      { number: 7, text: "Da sagte Adoni-Besek: Siebzig Könige, denen die Daumen ihrer Hände und <die großen Zehen> ihrer Füße abgehauen waren, lasen <Reste> auf unter meinem Tisch*. So wie ich getan habe, so hat Gott mir vergolten*. Und sie brachten ihn nach Jerusalem, dort starb er.", footnotes: ["℘ Mt 15,27", "℘ Kap. 9,24.57; 3Mo 24,19.20; 1Sam 15,33; 1Kö 21,19; Jes 33,1; Zef 3,19; Mt 7,1.2; Offb 22,12"] },
      { number: 8, text: "Und die Söhne Juda kämpften um Jerusalem und nahmen es ein und schlugen es mit der Schärfe des Schwertes, und die Stadt steckten sie in Brand*.", footnotes: ["℘ V. 21; Jos 15,63"] },
      { number: 9, text: "Danach zogen die Söhne Juda hinab, um gegen die Kanaaniter zu kämpfen, die das Gebirge und das Südland* und die Niederung* bewohnten*.", footnotes: ["hebr. Negev", "hebr. Schefelah; d. i. der Küstenstreifen zwischen Jafo und Gaza", "℘ Jos 12,8"] },
      { number: 10, text: "Und Juda ging gegen die Kanaaniter vor, die in Hebron wohnten; der Name Hebrons war aber früher Kirjat-Arba; und sie schlugen Scheschai und Ahiman und Talmai*.", footnotes: ["℘ Jos 15,13.14"] },
      { number: 11, text: "Und von dort ging er gegen die Bewohner von Debir vor; der Name von Debir war aber früher Kirjat-Sefer." },
      { number: 12, text: "*Und Kaleb sagte: Wer Kirjat-Sefer schlägt und es einnimmt, dem gebe ich meine Tochter Achsa zur Frau.", footnotes: ["℘ V. 12-15: Jos 15,16-19"] },
      { number: 13, text: "Da nahm es Otniël* ein, der Sohn des Kenas, der Bruder Kalebs — jünger als er —; und er gab ihm seine Tochter Achsa zur Frau.", footnotes: ["℘ Kap. 3,9-11"] },
      { number: 14, text: "Und es geschah, als sie herbeikam, da trieb sie ihn an*, von ihrem Vater das Feld zu fordern. Und sie sprang vom Esel herab. Da sagte Kaleb zu ihr: Was hast du?", footnotes: ["LXX und Vulg.: da trieb er sie an"] },
      { number: 15, text: "Und sie sagte zu ihm: Gib mir einen Segen*! Denn ein <dürres> Südland hast du mir gegeben*, so gib mir auch Wasserquellen! Da gab ihr Kaleb die oberen Quellen und die unteren Quellen.", footnotes: ["d. i. ein Geschenk, das durch einen Segensspruch begleitet und übertragen wird", "o. in ein <dürres> Südland hast du mich gegeben"] },
      { number: 16, text: "Und die Söhne des Keniters*, des Schwiegervaters des Mose*, waren mit den Söhnen Juda aus der Palmenstadt* heraufgezogen in die Wüste Juda, die im Süden von Arad <liegt>; und sie gingen hin und wohnten bei dem Volk*.", footnotes: ["LXX: Und die Söhne Hobabs, des Keniters\n℘ 1Chr 2,55", "℘ Kap. 4,11; 2Mo 18,1; 1Sam 15,6", "℘ Kap. 3,13; 5Mo 34,4; Jos 18,21", "Einige Handschr. von LXX, die alte lat. und die koptische Üs. lesen: wohnten bei den Amalekitern\n℘ 4Mo 10,29-32"] },
      { number: 17, text: "Und Juda zog mit seinem Bruder Simeon hin, und sie schlugen die Kanaaniter, die Zefat bewohnten. Und sie vollstreckten an ihnen den Bann und gaben der Stadt den Namen Horma*.", footnotes: ["d. h. Bann, o. Vernichtung\n℘ 4Mo 14,45"] },
      { number: 18, text: "Doch nahm Juda Gaza* und sein Gebiet nicht in Besitz*, ebenso Aschkelon* und sein Gebiet und Ekron* und sein Gebiet.", footnotes: ["℘ Kap. 16,1; 5Mo 2,23", "so mit LXX; Mas. T.: Und Juda nahm Gaza und sein Gebiet ein", "℘ Kap. 14,19", "℘ Jos 15,11; Jer 25,20"] },
      { number: 19, text: "Und der HERR war mit Juda*, und er nahm das Gebirge in Besitz. Aber die Bewohner der Ebene waren nicht zu vertreiben, weil sie eiserne Wagen hatten*.", footnotes: ["℘ 1Sam 18,12.14; 2Kö 18,7; Ps 60,14", "℘ Kap. 4,3; Jos 17,16"] },
      { number: 20, text: "Und sie gaben dem Kaleb Hebron, wie Mose geredet hatte*; und er vertrieb daraus die drei Söhne Enaks*.", footnotes: ["℘ Jos 14,9-14", "℘ Jos 15,13.14"] },
      { number: 21, text: "Aber die Söhne Benjamin vertrieben nicht die Jebusiter, die Bewohner von Jerusalem*. So blieben die Jebusiter bei den Söhnen Benjamin in Jerusalem wohnen bis auf diesen Tag*.", footnotes: ["℘ V. 27.29.31; Ps 106,34", "℘ V. 8; Kap. 19,11; Jos 18,28"] },
      { number: 22, text: "Und das Haus Josef, auch sie zogen nach Bethel hinauf*, und der HERR war mit ihnen*.", heading: "Nicht eroberte Gebiete in Nordkanaan", footnotes: ["℘ Jos 16,1", "℘ 1Mo 49,24"] },
      { number: 23, text: "Und das Haus Josef ließ Bethel auskundschaften*; der Name der Stadt aber war früher Lus*.", footnotes: ["℘ Jos 2,1; 16,2", "℘ Jos 16,1"] },
      { number: 24, text: "Und die Wachen sahen einen Mann aus der Stadt herauskommen, und sie sagten zu ihm: Zeig uns doch den Zugang zur Stadt, dann werden wir dir Gnade erweisen*!", footnotes: ["℘ Jos 2,12-14; 1Sam 30,15"] },
      { number: 25, text: "Da zeigte er ihnen den Zugang zur Stadt. Und sie schlugen die Stadt mit der Schärfe des Schwertes, aber den Mann und seine ganze Sippe ließen sie gehen*.", footnotes: ["℘ Jos 6,22-25"] },
      { number: 26, text: "Und der Mann zog in das Land der Hetiter. <Dort> baute er eine Stadt und gab ihr den Namen Lus. Das ist ihr Name bis auf diesen Tag." },
      { number: 27, text: "Aber Manasse vertrieb nicht Bet-Schean* und seine Tochterstädte, und Taanach und seine Tochterstädte, und die Bewohner von Dor und seine Tochterstädte, und die Bewohner von Jibleam und seine Tochterstädte, und die Bewohner von Megiddo* und seine Tochterstädte. Und die Kanaaniter vermochten* in diesem Land zu bleiben.", footnotes: ["℘ 1Sam 31,10", "℘ Jos 17,11-13; 2Kö 23,29", "o. setzten alles daran; o. erdreisteten sich"] },
      { number: 28, text: "Und es geschah, als Israel stark geworden war, da stellte es die Kanaaniter an die Zwangsarbeit*, doch vertreiben konnte es sie nicht. —", footnotes: ["℘ 1Mo 9,26"] },
      { number: 29, text: "Und Ephraim vertrieb nicht die Kanaaniter, die in Geser* wohnten. So blieben die Kanaaniter in seiner Mitte in Geser wohnen. —", footnotes: ["℘ Jos 16,10"] },
      { number: 30, text: "Sebulon vertrieb nicht die Bewohner von Kitron und die Bewohner von Nahalol*; so blieben die Kanaaniter in seiner Mitte wohnen und wurden zur Zwangsarbeit <herangezogen>. —", footnotes: ["℘ Jos 19,15"] },
      { number: 31, text: "Asser vertrieb nicht die Bewohner von Akko und die Bewohner von Sidon* und Achlab und Achsib und Helba und Afek und Rehob*,", footnotes: ["℘ 1Kö 16,31", "℘ Jos 19,24-30"] },
      { number: 32, text: "sondern die Asseriter wohnten mitten unter den Kanaanitern, den Bewohnern des Landes, denn sie hatten sie nicht vertrieben." },
      { number: 33, text: "Naftali vertrieb nicht die Bewohner von Bet-Schemesch und die Bewohner von Bet-Anat*, sondern er wohnte mitten unter den Kanaanitern, den Bewohnern des Landes; aber die Bewohner von Bet-Schemesch und von Bet-Anat wurden zur Zwangsarbeit für ihn <herangezogen>.", footnotes: ["℘ Jos 19,38"] },
      { number: 34, text: "Und die Amoriter drängten die Söhne Dan ins Gebirge, denn sie gaben <ihnen> nicht <die Möglichkeit>, in die Ebene herabzukommen*.", footnotes: ["℘ Kap. 18,1; Jos 19,47"] },
      { number: 35, text: "Und die Amoriter vermochten* im Gebirge Heres wohnen zu bleiben, in Ajalon und in Schaalbim*; aber die Hand des Hauses Josef wurde <auf ihnen> schwer, und sie wurden zur Zwangsarbeit <herangezogen>.", footnotes: ["o. setzten alles daran; o. erdreisteten sich", "℘ Jos 19,42"] },
      { number: 36, text: "Das Gebiet aber der Amoriter* war vom Anstieg Akrabbim*, vom Felsen* an, und weiter hinauf.", footnotes: ["LXX: Edomiter", "o. von der Skorpionensteige\n℘ 4Mo 34,4; 1Kö 9,21", "hebr. Sela; d. i. gleichlautend mit der edomitischen Stadt Sela in 2Kö 14,7"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "Und der Engel des HERRN* kam von Gilgal herauf nach Bochim; und er sprach: Ich habe euch aus Ägypten heraufgeführt und euch in das Land gebracht, das ich euren Vätern zugeschworen habe*. Und ich sagte: Ich werde meinen Bund mit euch nicht brechen in Ewigkeit*;", heading: "Gerichtswort des Engels von Bochim", footnotes: ["℘ Kap. 6,11; 1Mo 22,11", "℘ Kap. 11,24; 5Mo 1,8.35", "℘ 1Mo 17,7.8; Ps 89,3.4"] },
      { number: 2, text: "und ihr, ihr sollt keinen Bund mit den Bewohnern dieses Landes schließen, ihre Altäre sollt ihr niederreißen. Aber ihr habt meiner Stimme nicht gehorcht*. Was habt ihr da getan*!", footnotes: ["℘ Kap. 6,10; Ps 106,34", "℘ 1Mo 12,18"] },
      { number: 3, text: "So habe ich auch gesagt: Ich werde sie nicht vor euch vertreiben! Sie werden euch zu <Geißeln für eure> Seiten werden*, und ihre Götter werden euch zur Falle werden*.", footnotes: ["vgl. Jos 23,13; manche ergänzen nach 4Mo 33,55: Stacheln; andere ändern in: sie werden <eure> Feinde sein", "℘ Kap. 8,27; 2Mo 23,33"] },
      { number: 4, text: "Und es geschah, als der Engel des HERRN diese Worte zu allen Söhnen Israel geredet hatte, da erhob das Volk seine Stimme und weinte*.", footnotes: ["℘ 1Sam 7,6; 11,4; Esr 10,1; Joe 2,12; 2Kor 7,10"] },
      { number: 5, text: "Und sie gaben jenem Ort den Namen Bochim*. Und sie opferten dort dem HERRN.", footnotes: ["d. h. Weinende"] },
      { number: 6, text: "Und Josua entließ das Volk, und die Söhne Israel gingen hin, jeder in sein Erbteil, um das Land in Besitz zu nehmen*.", heading: "Josuas Tod und Begräbnis", footnotes: ["℘ Jos 24,28"] },
      { number: 7, text: "Und das Volk diente dem HERRN alle Tage Josuas und alle Tage der Ältesten, die nach Josua noch länger lebten*, die das ganze große Werk des HERRN gesehen hatten, das er für Israel getan hatte*.", footnotes: ["w. die ihre Tage verlängerten nach Josua", "℘ Jos 24,31"] },
      { number: 8, text: "Dann starb Josua, der Sohn des Nun, der Knecht des HERRN, 110 Jahre alt*.", footnotes: ["℘ Kap. 1,1; Jos 24,29.30"] },
      { number: 9, text: "Und sie begruben ihn im Gebiet seines Erbteils, in Timnat-Heres auf dem Gebirge Ephraim, nördlich vom Berg Gaasch*.", footnotes: ["℘ Kap. 1,1; Jos 24,29.30"] },
      { number: 10, text: "Und auch jene ganze Generation* wurde zu ihren Vätern versammelt. Und eine andere Generation kam nach ihnen auf, die den HERRN nicht kannte* und auch nicht das Werk, das er für Israel getan hatte*.", footnotes: ["d. h. alle, die zu Josuas Zeiten gelebt hatten", "℘ 2Mo 1,6.8; Jer 9,2", "℘ Jos 24,31"] },
      { number: 11, text: "Da taten die Söhne Israel, was böse war in den Augen des HERRN*, und dienten den Baalim*.", heading: "Die Richterzeit: eine Abfolge von Untreue, Gericht, Hilferuf und Rettung", footnotes: ["℘ Kap. 3,12; 4,1; 6,1; 10,6; 13,1", "℘ Kap. 3,7; 4Mo 25,3; 1Sam 7,3; 12,10; 1Kö 11,5; 2Chr 28,3; 33,3; Jer 2,20; 16,11"] },
      { number: 12, text: "Und sie verließen den HERRN, den Gott ihrer Väter*, der sie aus dem Land Ägypten herausgeführt hatte*, und liefen anderen Göttern nach, von den Göttern der Völker, die rings um sie her <lebten>*, und sie warfen sich vor ihnen nieder und reizten den HERRN zum Zorn*.", footnotes: ["℘ 5Mo 31,16", "℘ 2Mo 13,3.14; 5Mo 6,12", "℘ Kap. 5,8", "℘ 5Mo 4,25"] },
      { number: 13, text: "So verließen sie den HERRN und dienten dem Baal und den Astarot*.", footnotes: ["℘ Kap. 3,7; 4Mo 25,3; 1Sam 7,3; 12,10; 1Kö 11,5; 2Chr 28,3; 33,3; Jer 2,20; 16,11"] },
      { number: 14, text: "Da entbrannte der Zorn des HERRN gegen Israel*, und er gab sie in die Hand von Plünderern, die sie ausplünderten. Und er verkaufte sie in die Hand ihrer Feinde ringsum*, so dass sie vor ihren Feinden nicht mehr standhalten konnten*.", footnotes: ["℘ Kap. 3,8; 4Mo 32,13; Jos 23,16; 2Sam 24,1; Ps 106,40", "℘ Kap. 4,2; 10,7; 3Mo 26,17; 2Kö 13,3", "℘ 3Mo 26,37; Jos 7,12; 2Chr 28,5; Ps 44,11; Jes 42,24"] },
      { number: 15, text: "Überall, wohin sie auszogen, war die Hand des HERRN gegen sie zum Bösen*, ganz wie der HERR geredet und wie der HERR ihnen geschworen hatte*; so waren sie sehr bedrängt*.", footnotes: ["℘ Rt 1,13.21", "℘ 5Mo 18,20; 1Sam 12,15", "℘ Kap. 10,9; 2Chr 12,1.2"] },
      { number: 16, text: "Da ließ der HERR Richter aufstehen*, die retteten sie aus der Hand ihrer Plünderer*.", footnotes: ["℘ Rt 1,1; 2Sam 7,11; Neh 9,27; Apg 13,20", "℘ Kap. 3,31; 10,1; 11,32; 1Sam 14,48; Ps 106,43-45"] },
      { number: 17, text: "Aber auch auf ihre Richter hörten sie nicht*, sondern hurten anderen Göttern nach und warfen sich vor ihnen nieder*. Sie wichen schnell ab von dem Weg, den ihre Väter, um den Geboten des HERRN zu gehorchen, gegangen waren; sie handelten nicht so*.", footnotes: ["℘ 2Chr 36,16", "℘ 5Mo 31,16.18.29; Jer 3,6", "℘ Jer 6,16"] },
      { number: 18, text: "Und wenn der HERR ihnen Richter erstehen ließ, war der HERR mit dem Richter*, und er rettete sie aus der Hand ihrer Feinde alle Tage des Richters. Denn der HERR hatte Mitleid wegen ihres Ächzens über die, die sie quälten und sie bedrängten*.", footnotes: ["℘ Kap. 6,12", "℘ Kap. 3,9; 10,16; 2Mo 32,14; Ps 106,45"] },
      { number: 19, text: "Und es geschah, sobald der Richter gestorben war, kehrten sie um* und trieben es schlimmer als ihre Väter darin, anderen Göttern nachzulaufen, ihnen zu dienen und sich vor ihnen niederzuwerfen*. Sie ließen nichts fallen von ihren Taten und von ihrem halsstarrigen Wandel*.", footnotes: ["℘ 2Mo 32,7.8; Neh 9,28", "℘ Kap. 4,1; 8,33; 10,13", "℘ Jer 16,12"] },
      { number: 20, text: "Da entbrannte der Zorn des HERRN gegen Israel*, und er sprach: Weil diese Nation meinen Bund übertreten hat, den ich ihren Vätern geboten habe, und sie meiner Stimme nicht gehorcht haben,", footnotes: ["℘ Kap. 3,8; 4Mo 32,13; Jos 23,16; 2Sam 24,1; Ps 106,40"] },
      { number: 21, text: "so werde auch ich nicht länger irgendeinen vor ihnen vertreiben aus den Nationen*, die Josua übrig gelassen hat, als er starb*,", footnotes: ["o. nicht länger irgendeine von den Nationen vor ihnen vertreiben", "℘ Jos 23,13"] },
      { number: 22, text: "damit ich Israel durch sie prüfe*, ob sie den Weg des HERRN bewahren werden, darauf zu gehen, wie ihre Väter <ihn> bewahrt haben, oder nicht*.", footnotes: ["o. auf die Probe stelle; o. versuche", "℘ Kap. 3,1.4; 2Mo 15,25"] },
      { number: 23, text: "So ließ der HERR diese Nationen bleiben, ohne sie schnell zu vertreiben, und gab sie nicht in die Hand Josuas." },
    ]},
    { number: 3, verses: [
      { number: 1, text: "Das sind die Nationen, die der HERR bleiben ließ, um durch sie Israel zu prüfen*, alle <jene>, die all die Kriege um Kanaan nicht kannten —", heading: "Reste der Kanaaniter im Land Israels", footnotes: ["o. auf die Probe zu stellen; o. zu versuchen\n℘ Kap. 2,22"] },
      { number: 2, text: "nur damit er die Generationen der Söhne Israel erkenne, indem er sie den Krieg lehrte, <und zwar> nur die <Kriege> von damals, die sie nicht kannten* —:", footnotes: ["o. <und zwar> nur die, die die Kriege von damals nicht mehr kannten"] },
      { number: 3, text: "die fünf Fürsten der Philister und alle Kanaaniter und Sidonier und Hewiter, die das Gebirge Libanon bewohnten, vom Berg Baal-Hermon an, bis man nach Hamat kommt*.", footnotes: ["o. bis Lebo-Hamat\n℘ Jos 13,3-5"] },
      { number: 4, text: "Und sie dienten dazu, Israel durch sie zu prüfen*, damit man erkenne, ob sie den Geboten des HERRN gehorchten, die er ihren Vätern durch Mose geboten hatte.", footnotes: ["o. auf die Probe zu stellen; o. zu versuchen\n℘ Kap. 2,22"] },
      { number: 5, text: "Und die Söhne Israel wohnten mitten unter den Kanaanitern, den Hetitern und den Amoritern und den Perisitern und den Hewitern und den Jebusitern*.", footnotes: ["℘ Kap. 1,4.5; 1Kö 9,20"] },
      { number: 6, text: "Und sie nahmen sich deren Töchter als Frauen und gaben ihre Töchter deren Söhnen und dienten ihren Göttern*.", footnotes: ["℘ 2Mo 34,16; 1Kö 11,3; 2Kor 6,14"] },
      { number: 7, text: "Und die Söhne Israel taten, was böse war in den Augen des HERRN, und vergaßen den HERRN, ihren Gott*, und sie dienten den Baalim und den Ascheren*.", heading: "Die Richter Otniël, Ehud und Schamgar", footnotes: ["℘ 5Mo 8,11.14; 1Sam 12,9", "℘ Kap. 2,11; 6,25; 8,33; Ps 106,35.36"] },
      { number: 8, text: "Da entbrannte der Zorn des HERRN gegen Israel*, und er verkaufte sie in die Hand Kuschan-Rischatajims*, des Königs von Mesopotamien*; und die Söhne Israel dienten dem Kuschan-Rischatajim acht Jahre*.", footnotes: ["℘ Kap. 2,14", "d. h. Mohr der doppelten Bosheit", "hebr. Aram-Naharajim; d. i. Aram der beiden Flüsse\n℘ 1Mo 24,10", "℘ 3Mo 26,17; Ps 106,41"] },
      { number: 9, text: "Und die Söhne Israel schrien zu dem HERRN um Hilfe. Da ließ der HERR den Söhnen Israel einen Retter erstehen, der rettete sie*: Otniël, den Sohn des Kenas, den Bruder Kalebs*, der jünger war als er.", footnotes: ["℘ Kap. 2,16.18; 4,3", "℘ Kap. 1,13"] },
      { number: 10, text: "Und der Geist des HERRN kam über ihn*, und er richtete Israel. Und er zog aus zum Kampf, und der HERR gab Kuschan-Rischatajim, den König von Aram, in seine Hand, und seine Hand wurde stark über Kuschan-Rischatajim.", footnotes: ["℘ Kap. 6,34; 11,29; 13,25; 14,6.19; 15,14; 1Sam 10,6.10; 2Chr 15,1"] },
      { number: 11, text: "Und das Land hatte vierzig Jahre Ruhe*. Und Otniël, der Sohn des Kenas, starb.", footnotes: ["℘ V. 30; Kap. 5,31; 8,28"] },
      { number: 12, text: "Und die Söhne Israel taten weiter, was böse war in den Augen des HERRN*. Da machte der HERR Eglon, den König von Moab*, stark gegen Israel, weil sie taten, was böse war in den Augen des HERRN.", footnotes: ["℘ Kap. 2,11.19; Hos 6,4", "℘ 1Sam 12,9"] },
      { number: 13, text: "Und er sammelte die Söhne Ammon* und Amalek* um sich, zog hin und schlug Israel, und sie nahmen die Palmenstadt in Besitz*.", footnotes: ["℘ Kap. 6,3; 10,9.12; Ps 83,6-8", "℘ Kap. 2,22", "℘ Kap. 1,16"] },
      { number: 14, text: "Und die Söhne Israel dienten Eglon, dem König von Moab, achtzehn Jahre*.", footnotes: ["℘ 3Mo 26,17; Ps 106,41"] },
      { number: 15, text: "Da schrien die Söhne Israel zu dem HERRN um Hilfe, und der HERR ließ ihnen einen Retter erstehen*: Ehud, den Sohn des Gera*, einen Benjaminiter, einen Mann, der Linkshänder* war*. Und die Söhne Israel sandten durch seine Hand <ihren> Tribut an Eglon, den König von Moab*.", footnotes: ["℘ Kap. 2,16.18; 4,3", "℘ 1Chr 8,3.5", "w. an der rechten Hand gehemmt. — LXX: beidseitig rechtshändig", "℘ Kap. 20,16; 2Sam 20,9.10", "℘ 2Chr 9,24"] },
      { number: 16, text: "Und Ehud machte sich ein Schwert, das zwei Schneiden hatte, eine Elle seine Länge; das gürtete er unter seinem Gewand an seine rechte Hüfte." },
      { number: 17, text: "Und er überreichte Eglon, dem König von Moab, den Tribut. Eglon war aber ein sehr fetter Mann." },
      { number: 18, text: "Und es geschah, als er mit der Überreichung des Tributs fertig war, da entließ er das Volk, das den Tribut getragen hatte." },
      { number: 19, text: "Er selbst aber kehrte bei den Götterbildern, die bei Gilgal sind, um und sagte: Ein geheimes Wort habe ich an dich, König! Und er sprach: Still! Da gingen alle, die bei ihm standen, von ihm hinaus." },
      { number: 20, text: "Und Ehud kam zu ihm herein, als er gerade in dem kühlen Obergemach saß, das für ihn allein <bestimmt> war. Und Ehud sagte: Ein Wort Gottes habe ich an dich! Und er stand auf vom Sitz*.", footnotes: ["℘ 4Mo 23,18"] },
      { number: 21, text: "Da streckte Ehud seine linke Hand aus und nahm das Schwert von seiner rechten Hüfte und stieß es ihm in den Bauch." },
      { number: 22, text: "Und es drang sogar der Griff hinein nach der Klinge, und das Fett schloss sich um die Klinge, denn er zog das Schwert nicht aus seinem Bauch heraus; und es fuhr hinaus zwischen den Beinen*.", footnotes: ["o. und er entkam durch ein Schlupfloch"] },
      { number: 23, text: "Und Ehud ging in die Vorhalle* hinaus, aber die Tür* des Obergemachs hatte er hinter sich* verschlossen und verriegelt.", footnotes: ["nach anderen: durch den Abort", "w. die Türflügel", "o. hinter ihm; d. h. hinter Eglon"] },
      { number: 24, text: "Als er hinausgegangen war, kamen seine* Knechte und sahen, und siehe, die Tür* des Obergemachs war verriegelt. Da sagten sie: Er bedeckt gewiss nur seine Füße* in der kühlen Kammer.", footnotes: ["d. h. Eglons", "w. die Türflügel", "d. h. er verrichtet seine Notdurft"] },
      { number: 25, text: "Und sie warteten übermäßig lange*, aber siehe, er öffnete die Tür des Obergemachs nicht. Da nahmen sie den Schlüssel und schlossen auf, und siehe, ihr Herr lag tot am Boden. —", footnotes: ["w. bis zur Beschämung"] },
      { number: 26, text: "Ehud aber war entkommen, während sie zögerten: Er war über die Götterbilder hinausgelangt und entkam nach Seïra*.", footnotes: ["℘ 2Sam 4,6"] },
      { number: 27, text: "Und es geschah, sobald er <heim>gekommen war, stieß er ins Horn* auf dem Gebirge Ephraim*, und die Söhne Israel zogen mit ihm vom Gebirge hinab und er ihnen voran.", footnotes: ["℘ Kap. 6,34; 1Sam 13,3; Neh 4,14", "℘ Kap. 7,24; 10,1; 17,1; 19,1"] },
      { number: 28, text: "Und er sagte zu ihnen: Jagt mir nach, denn der HERR hat eure Feinde, die Moabiter, in eure Hand gegeben*! So zogen sie hinab, ihm nach, und nahmen den Moabitern die Furten des Jordan* und ließen niemanden hinübergehen.", footnotes: ["℘ Kap. 7,9", "o. und besetzten die Furten des Jordan<, die> nach Moab <führen>\n℘ Kap. 7,24; 12,5; Jos 2,7"] },
      { number: 29, text: "Und sie schlugen Moab in dieser Zeit, an die zehntausend Mann, alles kräftige und kriegstüchtige Männer*; nicht einer entkam.", footnotes: ["w. alles Fette und alles Männer der Schlacht"] },
      { number: 30, text: "So musste sich Moab an jenem Tag unter die Hand Israels beugen. Und das Land hatte achtzig Jahre Ruhe*.", footnotes: ["℘ V. 11"] },
      { number: 31, text: "Und nach ihm war Schamgar, der Sohn Anats*; und er schlug die Philister, sechshundert Mann, mit einem Viehtreiberstock*. Und auch er rettete Israel*.", footnotes: ["℘ Kap. 5,6", "℘ Kap. 15,15; 1Sam 17,50", "℘ Kap. 2,16; 10,11"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Und die Söhne Israel taten weiter, was böse war in den Augen des HERRN*, nachdem Ehud gestorben war*.", heading: "Debora und Barak — ihr Sieg über Jabin und Sisera", footnotes: ["℘ Kap. 2,11", "℘ Kap. 2,19"] },
      { number: 2, text: "Da verkaufte sie der HERR in die Hand Jabins, des Königs von Kanaan*, der in Hazor* König war. Sein Heeroberster war Sisera*, der wohnte in Haroschet-Gojim*.", footnotes: ["℘ Kap. 2,14", "℘ Jos 11,1", "℘ 1Sam 12,9", "d. h. Wald der Nationen"] },
      { number: 3, text: "Da schrien die Söhne Israel zu dem HERRN*; denn er hatte neunhundert eiserne Wagen*, und er quälte die Söhne Israel mit Gewalt* zwanzig Jahre.", footnotes: ["℘ Kap. 3,9.15; 6,6; 10,10; 2Mo 2,23", "℘ Kap. 1,19", "℘ Ps 106,42"] },
      { number: 4, text: "*Und Debora, eine Prophetin*, die Frau des Lappidot, war Richterin in Israel zu jener Zeit.", footnotes: ["℘ V. 4-16: Kap. 5,1-23", "℘ 2Mo 15,20"] },
      { number: 5, text: "Sie hatte ihren Sitz* unter der Debora-Palme, zwischen Rama und Bethel, im Gebirge Ephraim*. Und die Söhne Israel gingen zu ihr hinauf zum Gericht*.", footnotes: ["w. sie wohnte, o. sie saß<, um Recht zu sprechen>", "℘ 1Sam 1,1", "℘ 1Sam 7,17"] },
      { number: 6, text: "Und sie sandte hin und ließ Barak*, den Sohn Abinoams, aus Kedesch <in> Naftali* rufen. Und sie sagte zu ihm: Hat der HERR, der Gott Israels*, nicht geboten: Geh hin und zieh auf den Berg Tabor* und nimm mit dir zehntausend Mann von den Söhnen Naftali und von den Söhnen Sebulon?", footnotes: ["℘ 1Sam 12,11; Hebr 11,32", "℘ Jos 19,37", "℘ Hebr 11,16", "℘ Kap. 8,18; Jos 19,22; Ps 89,13; Jer 46,18; Hos 5,1"] },
      { number: 7, text: "Ich aber ziehe Sisera, den Heerobersten Jabins, zu dir heran* an den Bach Kischon* mit seinen Wagen und seiner Menge, und ich gebe ihn in deine Hand!", footnotes: ["℘ 2Mo 14,4", "℘ 1Kö 18,40"] },
      { number: 8, text: "Da sagte Barak zu ihr: Wenn du mit mir gehst, gehe ich; wenn du aber nicht mit mir gehst, gehe ich nicht." },
      { number: 9, text: "Da sagte sie: Ich will gerne mit dir gehen — nur dass <dann> die Ehre nicht dir <zufällt> auf dem Weg, den du gehst, denn in die Hand einer Frau wird der HERR den Sisera verkaufen*. Und Debora machte sich auf und ging mit Barak nach Kedesch.", footnotes: ["℘ Kap. 9,53.54"] },
      { number: 10, text: "Und Barak rief Sebulon und Naftali nach Kedesch zusammen. Und zehntausend Mann zogen in seinem Gefolge hinauf*; auch Debora zog mit ihm hinauf.", footnotes: ["℘ Kap. 6,35"] },
      { number: 11, text: "Heber aber, der Keniter, hatte sich von den Kenitern getrennt, <von> den Söhnen Hobabs, des Schwiegervaters des Mose*. Und er hatte sein Zelt aufgeschlagen bis zur Terebinthe in Zaanannim*, das bei Kedesch <liegt>.", footnotes: ["℘ Kap. 1,16; 4Mo 10,29", "℘ Jos 19,33"] },
      { number: 12, text: "Und man berichtete dem Sisera, dass Barak, der Sohn Abinoams, auf den Berg Tabor* hinaufgezogen sei.", footnotes: ["℘ Kap. 8,18; Jos 19,22; Ps 89,13; Jer 46,18; Hos 5,1"] },
      { number: 13, text: "Da rief Sisera alle seine Wagen zusammen, neunhundert eiserne Wagen, und das ganze <Kriegs>volk, das bei ihm war, von Haroschet-Gojim* an den Bach Kischon*.", footnotes: ["d. h. Wald der Nationen", "℘ 1Kö 18,40"] },
      { number: 14, text: "Debora aber sagte zu Barak: Mach dich auf! Denn dies ist der Tag, da der HERR den Sisera in deine Hand gegeben hat*. Ist nicht der HERR <selbst> vor dir her ausgezogen*? Und Barak stieg vom Berg Tabor hinab und zehntausend Mann ihm nach.", footnotes: ["℘ Kap. 7,9; Jos 10,8", "℘ 5Mo 9,3; 2Sam 5,24; Ps 68,8"] },
      { number: 15, text: "Und der HERR brachte Sisera und alle <seine> Wagen und das ganze Heerlager in Verwirrung durch die Schärfe des Schwertes vor Barak*. Und Sisera stieg vom Wagen herab und floh zu Fuß.", footnotes: ["℘ 1Sam 7,10"] },
      { number: 16, text: "Barak aber jagte den Wagen und dem Heer nach bis Haroschet-Gojim*. So fiel das ganze Heer Siseras durch die Schärfe des Schwertes; kein Einziger blieb übrig*.", footnotes: ["d. h. Wald der Nationen", "℘ Jos 10,10; Ps 83,10; Jes 43,17"] },
      { number: 17, text: "*Sisera aber floh zu Fuß zum Zelt Jaëls, der Frau Hebers, des Keniters; denn es war Friede zwischen Jabin, dem König von Hazor, und dem Haus Hebers, des Keniters.", footnotes: ["℘ V. 17-24: Kap. 5,24-31"] },
      { number: 18, text: "Da ging Jaël hinaus, dem Sisera entgegen. Und sie sagte zu ihm: Kehre ein, mein Herr, kehre ein zu mir, fürchte dich nicht! So kehrte er zu ihr ein in das Zelt, und sie bedeckte ihn mit einer Decke." },
      { number: 19, text: "Und er sagte zu ihr: Gib mir ein wenig Wasser zu trinken, denn ich bin durstig! Da öffnete sie den Milchschlauch, gab ihm zu trinken und deckte ihn <wieder> zu." },
      { number: 20, text: "Und er sagte zu ihr: Stell dich an den Eingang des Zeltes! Und es sei <so>: Wenn jemand kommt und dich fragt und sagt: Ist jemand hier?, dann sage: Niemand!" },
      { number: 21, text: "Jaël aber, die Frau Hebers, ergriff einen Zeltpflock und nahm den Hammer in ihre Hand, und sie ging leise zu ihm hinein und schlug den Pflock durch seine Schläfe, dass er in die Erde drang — er war nämlich in tiefen Schlaf gefallen —; da wurde er ohnmächtig und starb*.", footnotes: ["Eine andere hebr. Lesart lautet: Er war nämlich ermattet in tiefen Schlaf gefallen; so starb er"] },
      { number: 22, text: "Und siehe, als Barak Sisera nachjagte, da ging Jaël hinaus, ihm entgegen, und sagte zu ihm: Komm, ich will dir den Mann zeigen, den du suchst! Und er ging zu ihr hinein, und siehe, Sisera lag tot da, den Pflock in seiner Schläfe." },
      { number: 23, text: "So demütigte Gott an jenem Tag Jabin, den König von Kanaan, vor den Söhnen Israel." },
      { number: 24, text: "Und die Hand der Söhne Israel legte sich immer härter auf Jabin, den König von Kanaan, bis sie Jabin, den König von Kanaan, vernichtet hatten." },
    ]},
    { number: 5, verses: [
      { number: 1, text: "*Debora und Barak, der Sohn Abinoams, sangen* an jenem Tag folgendes <Lied>:", heading: "Siegeslied Deboras und Baraks", footnotes: ["℘ V. 1-23: Kap. 4,4-16", "℘ 2Mo 15,1; 2Sam 22,1"] },
      { number: 2, text: "Weil Führer führten in Israel*, weil freiwillig sich stellte das Volk*, dankt dem HERRN*!", footnotes: ["o. Als man in Israel das Haupthaar <zum Kampf> frei wachsen ließ; d. h. als viele zu kämpfen gelobten", "℘ 2Chr 17,16", "℘ Ps 103,2; 110,3"] },
      { number: 3, text: "Hört, ihr Könige! Horcht auf, ihr Fürsten! Ich will dem HERRN, ich will <ihm> singen, will spielen dem HERRN, dem Gott Israels*!", footnotes: ["℘ Ps 146,2"] },
      { number: 4, text: "HERR, als du auszogst von Seïr*, als du einherschrittest vom Gebiet Edoms*, bebte die Erde*, auch der Himmel triefte, ja, die Wolken trieften von Wasser.", footnotes: ["℘ 1Mo 32,4; 5Mo 33,2", "℘ 1Kö 18,40", "℘ 2Sam 22,8; Mi 1,4"] },
      { number: 5, text: "Die Berge erbebten vor dem HERRN, dem vom Sinai, vor dem HERRN, dem Gott Israels*.", footnotes: ["℘ Ps 68,9; 97,5; Jes 63,19; Nah 1,5"] },
      { number: 6, text: "In den Tagen Schamgars, des Sohnes Anats*, in den Tagen Jaëls ruhten die Wege*; und die auf Pfaden zogen, mussten gewundene Wege gehen.", footnotes: ["℘ Kap. 3,31", "Andere lesen mit anderer Vokalisierung: Karawanen\n℘ 3Mo 26,22; 2Chr 15,5"] },
      { number: 7, text: "Es ruhten die Landbewohner; sie ruhten* in Israel, bis ich, Debora, aufstand, bis ich aufstand, eine Mutter in Israel*.", footnotes: ["o. Es gab keine Führer mehr; sie gab es nicht mehr", "LXX und Vulg.: bis aufstand Debora, bis aufstand eine Mutter in Israel; andere ändern: bis du aufstandest . . ."] },
      { number: 8, text: "Man erwählte neue Götter*; da war Kampf* an den Toren! Wurden wohl Schild und Lanze gesehen unter 40 000 in Israel*?", footnotes: ["℘ Kap. 2,12.13; 5Mo 32,17; Jer 19,4", "Andere üs. mit Änderung eines Wortes: es gab kein Brot", "℘ 1Sam 13,19"] },
      { number: 9, text: "Mein Herz gehört den Gebietern Israels, denen, die sich freiwillig stellten im Volk*. Dankt dem HERRN*!", footnotes: ["℘ Ps 103,2; 110,3", "℘ Ps 103,2; 110,3"] },
      { number: 10, text: "Die ihr reitet auf weißen Eselinnen*, die ihr sitzt auf Teppichen und die ihr geht auf dem Weg, singt*!", footnotes: ["℘ Kap. 10,4; 12,14", "o. sagt es"] },
      { number: 11, text: "Lauter als die Wasserverteiler zwischen den Tränkrinnen sollen sie dort besingen die Heilstaten* des HERRN, die Heilstaten* an seinen Landbewohnern* in Israel*. Da zog das Volk des HERRN hinab zu den Toren.", footnotes: ["w. die Gerechtigkeiten", "w. die Gerechtigkeiten", "o. Führern", "℘ Ps 71,15.16"] },
      { number: 12, text: "Wach auf, wach auf, Debora! Wach auf, wach auf, sing* ein Lied*! Mache dich auf, Barak, und führe gefangen deine Gefangenen*, Sohn Abinoams!", footnotes: ["w. rede", "℘ Ps 57,9", "die syr. und arabische Üs.: führe gefangen fort, die dich gefangen fortgeführt haben"] },
      { number: 13, text: "Da zog, was entronnen war*, herab zu den Edlen des Volkes. HERR, ziehe herab zu mir mit den Helden!", footnotes: ["T.; Mas. T.: Dann ziehe, was übrig ist"] },
      { number: 14, text: "Von Ephraim, dessen Wurzeln sind wie <die von> Amalek*<, zogen sie herab>. Hinter dir her <Ephraim, zog auch> Benjamin* unter deinen Kriegsscharen*. Von Machir* zogen herab die Gebieter und von Sebulon* <alle>, die den Führerstab* halten.", footnotes: ["T.; Mas. T.: dessen Wurzeln in Amalek sind; gemeint ist: Ephraim, das so tapfer und heißblütig wie Amalek ist. Andere lesen mit mehrfach korrigiertem Text: Aus Ephraim zogen sie ins Tal\n℘ Kap. 12,15", "℘ 1Mo 35,24", "w. Völkern", "℘ 4Mo 32,39.40", "℘ 1Mo 35,23", "w. den Stab des Schreibers<, der das Volk für den Kriegsdienst musterte>"] },
      { number: 15, text: "Und die Obersten* in Issaschar waren mit Debora. Und <wie> Issaschar so Barak — in seinem Gefolge mitgerissen* ins Tal. An den Bächen* Rubens* waren großartige Beratungen* des Herzens.", footnotes: ["so mit Handschriften der LXX; Mas. T.: meine Obersten", "o. gesandt", "o. In den Bezirken", "℘ 1Mo 35,23", "so 5 hebr. Handschr. entsprechend V. 16; Mas. T.: Ordnungen, o. Festlegungen"] },
      { number: 16, text: "Warum bliebst du zwischen den Hürden*, das Flötenspiel bei den Herden zu hören*? An den Bächen* Rubens waren großartige Beratungen des Herzens.", footnotes: ["o. zwischen den beiden Sattelkörben; d. h. wie ein Packesel, der sich zwischen den Sattelkörben oft störrisch niederlegt", "℘ 4Mo 32,1-6", "o. In den Bezirken"] },
      { number: 17, text: "Gilead blieb untätig* jenseits des Jordan. Und Dan*, warum diente er auf fremden Schiffen*? Asser* saß an der Küste der Meere, und an seinen Buchten blieb er untätig*.", footnotes: ["w. hatte sich niedergelassen, o. blieb ruhig", "℘ 1Mo 35,25.26", "w. wozu hielt er sich als Fremder auf Schiffen auf", "℘ 1Mo 35,23", "w. wozu hielt er sich als Fremder auf Schiffen auf"] },
      { number: 18, text: "<Aber> Sebulon* ist ein Volk, das seine Seele dem Tod preisgab*, auch Naftali*, auf den Höhen des Gefildes.", footnotes: ["℘ 1Mo 35,25.26", "℘ Offb 12,11", "℘ Offb 12,11"] },
      { number: 19, text: "Könige kamen, sie kämpften; ja, da kämpften die Könige Kanaans in Taanach* am Wasser Megiddos*. Beute an Silber holten sie nicht*.", footnotes: ["℘ Jos 12,21", "℘ Jos 17,11; Offb 16,16", "℘ Ps 68,13"] },
      { number: 20, text: "Vom Himmel her kämpften die Sterne, von ihren Bahnen aus kämpften sie mit Sisera*.", footnotes: ["℘ Jos 10,11"] },
      { number: 21, text: "Der Bach Kischon riss sie hinweg*, der Bach der Urzeit, der Bach Kischon. Tritt auf, meine Seele, mit Kraft!", footnotes: ["℘ Ps 83,10"] },
      { number: 22, text: "Ja, da stampften die Hufe der Pferde vom Rennen, vom Rennen ihrer Hengste*.", footnotes: ["w. ihrer starken <Pferde>"] },
      { number: 23, text: "Verfluchet Meros! sprach der Engel des HERRN. Verfluchet, ja, verfluchet seine Bewohner! Denn sie sind dem HERRN nicht zu Hilfe gekommen, dem HERRN zu Hilfe unter den Helden*.", footnotes: ["℘ Kap. 8,5-9; 21,8.9; Jer 48,10"] },
      { number: 24, text: "*Gesegnet vor <allen> Frauen sei Jaël*, die Frau Hebers, des Keniters, vor <allen> Frauen im Zelt sei sie gesegnet!", footnotes: ["℘ V. 24-31: Kap. 4,17-24", "℘ Lk 1,42"] },
      { number: 25, text: "Wasser verlangte er, Milch gab sie; in einer kostbaren Schale* reichte sie Rahm.", footnotes: ["w. in einer Schale der Edlen"] },
      { number: 26, text: "Ihre Hand streckte sie aus nach dem Pflock, und ihre Rechte nach dem Arbeitshammer. Und sie schlug Sisera <mit dem Hammer>, zerschmetterte sein Haupt, sie zerschlug und durchbohrte seine Schläfe." },
      { number: 27, text: "Zwischen ihren Füßen krümmte er sich, fiel, lag da; zwischen ihren Füßen krümmte er sich, fiel; da, wo er sich krümmte, fiel er — vernichtet." },
      { number: 28, text: "Durchs Fenster schaute und jammerte Siseras Mutter — durchs Gitter*: Warum zögert sein Wagen zu kommen? Warum säumen die Tritte seiner Gespanne?", footnotes: ["℘ Spr 7,6; Hl 2,9"] },
      { number: 29, text: "Die Klugen unter ihren Edelfrauen erwidern ihr, auch selbst beantwortet sie sich ihre Reden:" },
      { number: 30, text: "Finden sie nicht, teilen sie nicht Beute*? Ein Mädchen, zwei Mädchen auf den Kopf eines Mannes? Beute an bunten Gewändern für Sisera, Beute an bunten Gewändern; ein farbiges Tuch, bunt, zwei farbige Tücher als Beute für meinen Hals*. —", footnotes: ["℘ 2Mo 15,9; Jes 9,2", "so mit anderer Vokalisierung; Mas. T.: für die Hälse der Beute"] },
      { number: 31, text: "So sollen umkommen alle deine Feinde, HERR*! Aber die, die ihn lieben*, <sollen sein,> wie die Sonne aufgeht in ihrer Kraft*! — Und das Land hatte vierzig Jahre Ruhe*.", footnotes: ["℘ 2Sam 18,32; Ps 92,10", "℘ 5Mo 7,9; 1Kor 2,9", "℘ 2Sam 23,4; Ps 19,6; Spr 4,18; Dan 12,3; Mt 13,43", "℘ Kap. 3,11.30"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "Und die Söhne Israel taten, was böse war in den Augen des HERRN*. Da gab sie der HERR in die Hand Midians*, sieben Jahre.", heading: "Gideons Berufung zum Kampf gegen die Midianiter", footnotes: ["℘ Kap. 2,11.19", "℘ Kap. 10,7; 4Mo 25,17"] },
      { number: 2, text: "Und die Hand Midians wurde stark über Israel*. Vor Midian machten sich die Söhne Israel die Felsenlöcher*, die in den Bergen sind, und die Höhlen und die Bergfesten*.", footnotes: ["℘ Kap. 10,8.9; 3Mo 26,17", "als unterirdische Depots", "o. die unzugänglichen Plätze\n℘ 1Sam 13,6; Hi 30,6"] },
      { number: 3, text: "Und es geschah, wenn Israel gesät hatte, dann zog Midian herauf und Amalek* und die Söhne des Ostens*, die zogen herauf gegen sie.", footnotes: ["℘ Kap. 3,13; 10,12; 2Mo 17,8", "℘ V. 33; 1Mo 25,6; 1Kö 5,10; Hi 1,3; Jes 11,14; Jer 49,28; Hes 25,3"] },
      { number: 4, text: "Und sie lagerten sich gegen sie und verheerten den Ertrag des Landes bis dahin, wo man nach Gaza* kommt. Und sie ließen keine Lebensmittel in Israel übrig, weder Schafe noch Rinder, noch Esel*.", footnotes: ["℘ 1Mo 10,19", "℘ 5Mo 28,31; Jer 5,17; Mi 6,15"] },
      { number: 5, text: "Denn sie zogen herauf mit ihren Herden und mit ihren Zelten und kamen so massenhaft wie Heuschrecken*; zahllos waren sie und ihre Kamele. Und sie kamen ins Land, um es zu verheeren*.", footnotes: ["℘ Kap. 7,12; Jer 46,23; 51,14", "℘ 5Mo 28,33.51"] },
      { number: 6, text: "So verarmte Israel sehr wegen Midian*. Und die Söhne Israel schrien zu dem HERRN um Hilfe*.", footnotes: ["℘ Ps 106,43", "℘ Kap. 4,3; 10,10; Hos 5,15"] },
      { number: 7, text: "Und es geschah, als die Söhne Israel wegen Midian zu dem HERRN um Hilfe schrien," },
      { number: 8, text: "da sandte der HERR einen Propheten zu den Söhnen Israel*. Dieser sagte zu ihnen: So spricht der HERR, der Gott Israels: Ich habe euch aus Ägypten heraufkommen lassen und habe euch herausgeführt aus dem Sklavenhaus*.", footnotes: ["℘ 2Kö 17,13; Ps 106,44", "℘ Kap. 2,1.2; 2Mo 13,3"] },
      { number: 9, text: "Und ich habe euch aus der Hand der Ägypter gerettet und aus der Hand all eurer Unterdrücker*. Und ich habe sie vor euch vertrieben und euch ihr Land gegeben*.", footnotes: ["o. all derer, die euch <aus dem Land> verdrängen wollten; o. die euch quälten", "℘ 2Mo 33,2; 1Sam 10,18; Ps 105,43.44"] },
      { number: 10, text: "Und ich sprach zu euch: Ich bin der HERR, euer Gott: Ihr sollt nicht die Götter der Amoriter fürchten, in deren Land ihr wohnt*. Aber ihr habt meiner Stimme nicht gehorcht*.", footnotes: ["℘ 2Mo 20,2.3; 34,12-16; 2Kö 17,35-38", "℘ 2Kö 17,13.14; Neh 9,29; Jer 17,23"] },
      { number: 11, text: "Und der Engel des HERRN* kam und setzte sich unter die Terebinthe, die bei Ofra war, die Joasch, dem Abiësriter* gehörte. Und sein Sohn Gideon* schlug gerade Weizen aus in der Kelter*, um ihn vor Midian in Sicherheit zu bringen.", footnotes: ["℘ Kap. 2,1", "℘ Kap. 8,2; Jos 17,2", "℘ Kap. 9,5; Hebr 11,32", "℘ 1Kö 19,19"] },
      { number: 12, text: "Da erschien ihm der Engel des HERRN* und sprach zu ihm: Der HERR ist mit dir*, du tapferer Held*!", footnotes: ["℘ Kap. 13,3", "℘ Kap. 2,18; 2Mo 3,12; 5Mo 20,1; Rt 2,4; Lk 1,28", "℘ Kap. 11,1"] },
      { number: 13, text: "Gideon aber sagte zu ihm: Bitte, mein Herr, wenn der HERR mit uns ist, warum hat uns denn das alles getroffen*? Und wo sind all seine Wunder, von denen uns unsere Väter erzählt haben, wenn sie sagten: Hat der HERR uns nicht aus Ägypten heraufkommen lassen*? Jetzt aber hat uns der HERR verworfen und uns in die Hand Midians gegeben.", footnotes: ["℘ 5Mo 31,17", "℘ Ps 44,2; Jes 63,11-13"] },
      { number: 14, text: "Da wandte sich der HERR ihm zu und sprach: Geh hin in dieser deiner Kraft und rette Israel aus der Hand Midians! Habe ich dich nicht gesandt*?", footnotes: ["℘ 2Mo 3,10; 1Sam 12,11"] },
      { number: 15, text: "Er aber sagte zu ihm: Bitte, mein Herr, womit soll ich Israel retten? Siehe, meine Tausendschaft ist die geringste in Manasse, und ich bin der Jüngste im Haus meines Vaters*.", footnotes: ["℘ 2Mo 3,11; 1Sam 9,21"] },
      { number: 16, text: "Da sprach der HERR zu ihm: Ich werde mit dir sein*, und du wirst Midian schlagen wie einen einzelnen Mann*.", footnotes: ["℘ Kap. 2,18; 2Mo 3,12; 5Mo 20,1; Rt 2,4; Lk 1,28", "℘ Jos 10,8; Jes 41,10-16"] },
      { number: 17, text: "Da sagte er zu ihm: Wenn ich denn Gunst gefunden habe in deinen Augen, so gib mir ein Zeichen, dass du es bist, der mit mir redet*.", footnotes: ["℘ 1Mo 15,8; 2Mo 4,1-9; Ps 86,17"] },
      { number: 18, text: "Weiche doch nicht von hier, bis ich zu dir <zurück>komme und meine Gabe herausbringe und dir vorsetze*! Er sprach: Ich will bleiben, bis du wiederkommst.", footnotes: ["℘ Kap. 13,15; 1Mo 18,3.5-8"] },
      { number: 19, text: "Da ging Gideon hinein und bereitete ein Ziegenböckchen zu und ungesäuerte Brote aus einem Efa Mehl. Das Fleisch tat er in einen Korb, und die Brühe tat er in einen Topf. Und er brachte es zu ihm hinaus unter die Terebinthe und legte <es> vor*.", footnotes: ["℘ Kap. 13,15; 1Mo 18,3.5-8"] },
      { number: 20, text: "Und der Engel Gottes sprach zu ihm: Nimm das Fleisch und die ungesäuerten Brote und lege es hin auf diesen Felsen da! Die Brühe aber gieße aus! Und er machte es so*.", footnotes: ["℘ Kap. 13,15; 1Mo 18,3.5-8"] },
      { number: 21, text: "Da streckte der Engel des HERRN das Ende des Stabes aus, der in seiner Hand war, und berührte das Fleisch und die ungesäuerten Brote*. Da stieg Feuer aus dem Felsen auf und verzehrte das Fleisch und die ungesäuerten Brote. Und der Engel des HERRN entschwand seinen Augen.", footnotes: ["℘ Kap. 13,20; 3Mo 9,24"] },
      { number: 22, text: "Da sah Gideon, dass es der Engel des HERRN gewesen war, und Gideon sagte: Wehe, Herr, HERR! Wahrhaftig, habe ich doch den Engel des HERRN von Angesicht zu Angesicht gesehen*!", footnotes: ["℘ Kap. 13,22; Jes 6,5; Lk 1,12"] },
      { number: 23, text: "Da sprach der HERR zu ihm: Friede <sei mit> dir*! Fürchte dich nicht*, du wirst nicht sterben*.", footnotes: ["℘ Kap. 19,20; Dan 10,19", "℘ Kap. 13,15; 1Mo 18,3.5-8", "℘ 1Mo 32,31"] },
      { number: 24, text: "Und Gideon baute dem HERRN dort einen Altar* und nannte ihn: Jahwe-Schalom*. Bis zu diesem Tag <steht> er noch in Ofra<, der Stadt> der Abiësriter*.", footnotes: ["℘ Kap. 21,4; 1Mo 12,7.8; 1Sam 7,17; 2Sam 24,25; 1Kö 18,32; Esr 3,2", "d. h. der HERR ist Friede o. Heil", "℘ Kap. 8,27.32"] },
      { number: 25, text: "Und es geschah in jener Nacht, da sprach der HERR zu ihm: Nimm einen Stier von den Rindern, die deinem Vater gehören, und zwar den zweiten Stier*, den siebenjährigen! Und reiße den Altar des Baal, der deinem Vater gehört, nieder und die Aschera, die dabei<steht>, haue um*!", footnotes: ["o. und den zweiten Stier", "℘ Kap. 3,7; 2Mo 34,13"] },
      { number: 26, text: "Und baue dem HERRN, deinem Gott, einen Altar auf dem Gipfel dieser Bergfeste* in der <rechten> Weise*! Und nimm den zweiten Stier und opfere <ihn> als Brandopfer mit dem Holz der Aschera, die du umhauen sollst*!", footnotes: ["9 hebr. Handschr. lesen: oben auf dieser Wohnung", "o. in der <üblichen> Anordnung; o. mit der Steinschicht <des früheren Altars>\n℘ 2Sam 24,22-25", "℘ 1Sam 6,14"] },
      { number: 27, text: "Da nahm Gideon zehn Männer von seinen Knechten und tat, wie der HERR zu ihm geredet hatte. Und es geschah, da er sich vor dem Haus seines Vaters und vor den Männern der Stadt fürchtete, es bei Tag zu tun, tat er es bei Nacht." },
      { number: 28, text: "Und als die Männer der Stadt morgens früh aufstanden, siehe, da war der Altar des Baal umgerissen, und die Aschera, die dabei<gestanden hatte>, war umgehauen, und der zweite Stier war als Brandopfer auf dem <neu> erbauten Altar geopfert." },
      { number: 29, text: "Da sagten sie einer zum anderen: Wer hat das getan? Und sie forschten und fragten nach, und man sagte: Gideon, der Sohn des Joasch, hat das getan." },
      { number: 30, text: "Da sagten die Männer der Stadt zu Joasch: Führe deinen Sohn heraus! Er muss sterben, weil er den Altar des Baal umgerissen und weil er die Aschera, die dabei<stand>, umgehauen hat!" },
      { number: 31, text: "Joasch aber sagte zu allen, die bei ihm standen: Wollt ihr für den Baal Anklage erheben*, oder wollt ihr ihn retten? Wer für ihn Anklage erhebt*, soll getötet werden bis zum Morgen*. Wenn er ein Gott ist, soll er für sich selbst Anklage erheben*, weil man seinen Altar umgerissen hat.", footnotes: ["w. den Rechtsstreit führen", "w. den Rechtsstreit führt", "℘ 5Mo 17,2-5", "w. den Rechtsstreit führt"] },
      { number: 32, text: "Und man nannte ihn an selbigem Tag Jerubbaal*, das heißt: Baal möge gegen ihn Anklage erheben*, weil er seinen Altar umgerissen hat.", footnotes: ["℘ Kap. 7,1", "w. den Rechtsstreit führen"] },
      { number: 33, text: "Und ganz Midian und Amalek und die Söhne des Ostens* versammelten sich miteinander, und sie zogen herüber und lagerten sich im Tal Jesreel*.", footnotes: ["℘ V. 3", "℘ Kap. 7,1.8; Jos 17,16"] },
      { number: 34, text: "Aber der Geist des HERRN umkleidete Gideon*. Und er stieß ins Horn*, und die Abiësriter wurden zusammengerufen, ihm nach.", footnotes: ["℘ Kap. 3,10; 1Chr 12,19", "℘ Kap. 3,27"] },
      { number: 35, text: "Und er sandte Boten durch den ganzen <Stamm> Manasse, und auch er wurde zusammengerufen, ihm nach. Und er sandte Boten durch Asser und durch Sebulon und durch Naftali. Und sie zogen herauf, ihnen entgegen*.", footnotes: ["℘ Kap. 4,10"] },
      { number: 36, text: "Und Gideon sagte zu Gott: Wenn du Israel durch meine Hand retten willst, so wie du geredet hast —" },
      { number: 37, text: "siehe, ich lege <frisch> geschorene Wolle* auf die Tenne. Wenn Tau auf der Wolle* allein sein wird und auf dem ganzen Boden Trockenheit, dann werde ich erkennen*, dass du Israel durch meine Hand retten wirst, wie du geredet hast.", footnotes: ["w. die Schur der Wolle", "w. Schur; so auch in folgenden Versen", "℘ 1Mo 24,14"] },
      { number: 38, text: "Und es geschah so. Und er stand am anderen Morgen früh auf, und er drückte die Wolle aus und presste Tau aus der Wolle, eine <ganze> Schale voll Wasser." },
      { number: 39, text: "Und Gideon sagte zu Gott: Dein Zorn entbrenne nicht gegen mich! Und ich will nur noch diesmal reden. Lass es mich doch nur noch diesmal mit der Wolle versuchen*: Möge doch Trockenheit sein auf der Wolle allein, und auf dem ganzen Boden sei Tau!", footnotes: ["℘ 1Mo 18,30.32"] },
      { number: 40, text: "Und Gott machte es so in jener Nacht*: Es war Trockenheit auf der Wolle allein, und auf dem ganzen Boden war Tau.", footnotes: ["℘ Jes 7,11.14"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "Und Jerubbaal, das ist Gideon*, und alles Volk, das bei ihm war, machten sich früh auf und lagerten sich an der Quelle Harod*: Das Heerlager Midians aber war nördlich von ihm, am Hügel More*, im Tal*.", heading: "Gideons Sieg über die Midianiter", footnotes: ["℘ Kap. 6,32", "℘ 1Sam 29,1; 2Sam 23,25", "o. vom Hügel More an", "℘ Kap. 6,33"] },
      { number: 2, text: "Und der HERR sprach zu Gideon: Zu zahlreich ist das Volk, das bei dir ist, als dass ich Midian in ihre Hand geben könnte. Israel soll sich nicht gegen mich rühmen können und sagen: Meine Hand hat mich gerettet*!", footnotes: ["℘ 5Mo 8,17; Jes 10,13; 1Kor 1,29"] },
      { number: 3, text: "Und nun rufe doch vor den Ohren des Volkes aus: Wer furchtsam und verzagt ist*, kehre um und wende sich zurück vom Gebirge Gilead! Da kehrten von dem Volk 22 000 <Mann> um, und 10 000 blieben übrig.", footnotes: ["℘ 5Mo 20,8"] },
      { number: 4, text: "Und der HERR sprach zu Gideon: Noch <immer> ist das Volk zu zahlreich*. Führe sie ans Wasser hinab, ich will sie dir dort läutern*! Und es soll geschehen, von wem ich dir sagen werde: Dieser soll mit dir gehen! — der soll mit dir gehen. Und jeder, von dem ich dir sagen werde: Dieser soll nicht mit dir gehen! — der soll nicht gehen.", footnotes: ["℘ Ps 33,16", "o. prüfen"] },
      { number: 5, text: "Da führte er das Volk ans Wasser hinab. Und der HERR sprach zu Gideon: Jeden, der mit seiner Zunge vom Wasser leckt, wie ein Hund leckt, den stelle gesondert für sich; und auch jeden, der sich auf seine Knie niederlässt, um zu trinken!" },
      { number: 6, text: "Und die Zahl derer, die leckten<, indem sie das Wasser> mit ihrer Hand an ihren Mund <brachten>, betrug dreihundert Mann; und der ganze Rest des Volkes hatte sich auf seine Knie niedergelassen, um Wasser zu trinken." },
      { number: 7, text: "Da sprach der HERR zu Gideon: Mit den dreihundert Mann, die geleckt haben, will ich euch retten und Midian in deine Hand geben*. Das ganze <übrige> Volk aber soll gehen, jeder an seinen Ort.", footnotes: ["℘ 1Sam 14,6"] },
      { number: 8, text: "Und sie nahmen die Wegzehrung des <übrigen> Volkes an sich* und deren Hörner. So entließ er alle Männer von Israel, jeden in seine Zelte; aber die dreihundert Mann behielt er da. Das Heerlager Midians war aber unter ihm im Tal*.", footnotes: ["T.; Mas. T.: Und das Volk nahm Wegzehrung mit sich", "℘ Kap. 6,33"] },
      { number: 9, text: "Und es geschah in derselben Nacht*, da sprach der HERR zu ihm: Mach dich auf, geh in das Heerlager hinab, denn ich habe es in deine Hand gegeben*!", footnotes: ["℘ 1Mo 46,2; Apg 18,9", "℘ Kap. 3,28; 4,14; 1Sam 23,4"] },
      { number: 10, text: "Und wenn du dich fürchtest hinabzugehen, dann geh du mit deinem Burschen Pura zum Heerlager hinab!" },
      { number: 11, text: "Da wirst du hören, was sie reden. Und danach werden deine Hände stark werden, so dass du in das Heerlager hinabgehen kannst. Da ging er hinab, er und sein Bursche Pura, <bis> in unmittelbare Nähe* der Gerüsteten, die im Heerlager waren.", footnotes: ["w. an die Enden; d. h. bis an die äußersten Vorposten"] },
      { number: 12, text: "Und Midian und Amalek und alle Söhne des Ostens waren in das Tal eingefallen wie die Heuschrecken an Menge*. Zahllos waren ihre Kamele, wie der Sand, der am Ufer des Meeres ist, an Menge.", footnotes: ["℘ Kap. 6,5; Jos 11,4; 1Sam 13,5; 1Kö 20,27"] },
      { number: 13, text: "Und als Gideon ankam, siehe, da erzählte ein Mann seinem Gefährten gerade einen Traum und sagte: Siehe, ich habe einen Traum gehabt. Und siehe, ein Laib Gerstenbrot rollte in das Heerlager Midians. Und es kam bis zum Zelt und schlug es nieder, dass es umfiel, und kehrte es um, <das Unterste> zu oberst, und das Zelt lag da*.", footnotes: ["℘ Kap. 8,10"] },
      { number: 14, text: "Da antwortete sein Gefährte und sagte: Das ist nichts anderes als das Schwert Gideons, des Sohnes des Joasch, des Mannes von Israel! Gott hat Midian und das ganze Heerlager in seine Hand gegeben*!", footnotes: ["℘ Kap. 3,28; 1Sam 14,12"] },
      { number: 15, text: "Und es geschah, als Gideon die Erzählung des Traumes und seine Deutung hörte, da betete er an*. Und er kehrte ins Heerlager Israels zurück und sagte: Macht euch auf! Denn der HERR hat das Heerlager Midians in eure Hand gegeben*.", footnotes: ["w. da warf er sich nieder <vor dem HERRN>\n℘ 1Mo 24,26.27; 1Sam 1,28", "℘ Kap. 3,28; 1Sam 14,12"] },
      { number: 16, text: "Und er teilte die dreihundert Mann in drei Abteilungen* und gab ihnen allen Hörner in die Hand und leere Krüge, und in den Krügen waren Fackeln.", footnotes: ["℘ 1Sam 11,11"] },
      { number: 17, text: "Und er sagte zu ihnen: Seht es mir ab und macht es ebenso! Siehe, wenn ich an den Rand des Heerlagers komme, dann soll es geschehen, dass ihr es ebenso macht, wie ich es mache!" },
      { number: 18, text: "Und stoße ich ins Horn, ich und alle, die bei mir sind, dann sollt auch ihr ins Horn stoßen rings um das ganze Heerlager und sollt rufen: Für den HERRN und für Gideon!" },
      { number: 19, text: "Und Gideon und die hundert Mann, die bei ihm waren, kamen an den Rand des Heerlagers, beim Beginn der mittleren Nachtwache; man hatte eben die Wachen aufgestellt. Und sie stießen in die Hörner und zerschmetterten die Krüge, die sie in der Hand hatten." },
      { number: 20, text: "Da stießen <auch> die drei Abteilungen in die Hörner und zerbrachen die Krüge. Und sie ergriffen mit ihrer linken Hand die Fackeln und mit ihrer rechten Hand die Hörner zum Blasen und riefen: Schwert für den HERRN und für Gideon!" },
      { number: 21, text: "Und sie blieben stehen, jeder an seiner Stelle, rings um das Heerlager*. Da lief das ganze Heerlager <durcheinander>, und sie schrien laut und flohen*.", footnotes: ["℘ 2Chr 20,17", "℘ 2Kö 7,6.7"] },
      { number: 22, text: "Während nun die dreihundert <Mann> in die Hörner stießen*, da richtete der HERR das Schwert des einen gegen den andern*, und zwar im ganzen Heerlager. Und das Heerlager floh bis Bet-Schitta, nach Zereda* hin, bis an die Grenze von Abel-Mehola* bei Tabbat.", footnotes: ["℘ Jos 6,16.20", "℘ 1Sam 14,20; 2Chr 20,23; Jes 9,3; Sach 14,13", "so mehrere hebr. Handschr. mit 1Kö 11,26; Mas. T.: Zerera\n℘ Jos 3,16", "℘ 1Kö 4,12"] },
      { number: 23, text: "Und es wurden die Männer Israels zusammengerufen aus Naftali, aus Asser und aus ganz Manasse, und sie jagten Midian nach*.", footnotes: ["℘ 3Mo 26,7; 1Sam 14,21.22; 1Kö 20,20"] },
      { number: 24, text: "Und Gideon sandte Boten in das ganze Gebirge Ephraim* und <ließ> sagen: Kommt herab, Midian entgegen! Und nehmt ihnen die Wasser<stellen>* bis Bet-Bara und den Jordan! Da wurden alle Männer Ephraims zusammengerufen, und sie nahmen <ihnen> die Wasser<stellen> bis Bet-Bara und den Jordan.", footnotes: ["℘ Kap. 3,27.28", "℘ Kap. 3,28; 1Sam 14,12"] },
      { number: 25, text: "Und sie nahmen zwei Oberste von Midian, Oreb und Seeb*, gefangen. Und sie erschlugen Oreb an dem Felsen Oreb*, und Seeb erschlugen sie bei der Kelter Seeb; und sie jagten Midian nach. Und die Köpfe Orebs und Seebs brachten sie zu Gideon auf die andere Seite des Jordan.", footnotes: ["℘ Kap. 8,3; Ps 83,10.12", "℘ Jes 10,26"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "Die Männer von Ephraim aber sagten zu ihm: Was ist das für eine Sache, die du uns da angetan hast, dass du uns nicht gerufen hast, als du hingingst, um mit Midian zu kämpfen! Und sie machten ihm heftige Vorwürfe*.", heading: "Verfolgung der Midianiter", footnotes: ["℘ Kap. 12,1; 2Sam 19,42-44; Hos 13,1"] },
      { number: 2, text: "Er sagte zu ihnen: Was habe ich denn geleistet im Vergleich zu euch? Ist nicht die Nachlese Ephraims besser als die Weinlese Abiësers*?", footnotes: ["℘ Kap. 6,11"] },
      { number: 3, text: "In eure Hand hat Gott die Obersten von Midian, Oreb und Seeb, gegeben*. Und was habe ich tun können im Vergleich zu euch? Da ließ ihr Zorn von ihm ab, als er dieses Wort redete*.", footnotes: ["℘ Kap. 7,24.25", "℘ Spr 15,1.23"] },
      { number: 4, text: "Und Gideon kam an den Jordan. Er ging hinüber, er und die dreihundert Mann, die bei ihm waren, erschöpft von der Verfolgung*.", footnotes: ["w. als Erschöpfte und Verfolgende; mehrere LXX-Handschr.: erschöpft und hungrig\n℘ 1Sam 30,8.10"] },
      { number: 5, text: "Und er sagte zu den Männern von Sukkot*: Gebt doch dem <Kriegs>volk, das in meinem Gefolge ist, Brot*, denn sie sind erschöpft! Und ich jage den Königen von Midian, Sebach und Zalmunna, nach.", footnotes: ["℘ 1Mo 33,17", "w. <einige> Fladen Brot"] },
      { number: 6, text: "Aber die Obersten von Sukkot sagten: Ist etwa die Faust Sebachs und Zalmunnas schon in deiner Hand, dass wir deinem Heer Brot geben sollten*?", footnotes: ["℘ Kap. 5,23; 1Sam 25,11"] },
      { number: 7, text: "Da sagte Gideon: Fürwahr, wenn der HERR Sebach und Zalmunna in meine Hand gegeben hat, werde ich euer Fleisch dreschen mit Dorngestrüpp der Wüste und mit Stechdisteln!" },
      { number: 8, text: "Und er zog von dort <weiter> nach Pnuël hinauf und redete zu denen ebenso. Aber die Männer von Pnuël* antworteten ihm, wie die Männer von Sukkot geantwortet hatten*.", footnotes: ["℘ 1Mo 32,32", "℘ Kap. 5,23; 1Sam 25,11"] },
      { number: 9, text: "Da sagte er auch zu den Männern von Pnuël: Wenn ich in Frieden zurückkomme, werde ich diesen Turm niederreißen!" },
      { number: 10, text: "Sebach und Zalmunna waren aber in Karkor und ihr Heerlager mit ihnen, etwa 15 000 <Mann>, alle, die übrig geblieben waren vom ganzen Heerlager der Söhne des Ostens. 120 000 Mann aber, die das Schwert zogen, waren gefallen*.", footnotes: ["℘ Kap. 7,12.13"] },
      { number: 11, text: "Und Gideon zog die Beduinenstraße* hinauf, östlich von Nobach und Jogboha*. Und er schlug das Heerlager, während das Heerlager sorglos war*.", footnotes: ["w. den Weg der bewohnten Zelte", "℘ 4Mo 32,35.42", "℘ 1Sam 30,16; 1Thes 5,3"] },
      { number: 12, text: "Und Sebach und Zalmunna flohen, er aber jagte ihnen nach und fing die beiden Könige von Midian, Sebach und Zalmunna. Und das ganze Heerlager setzte er in Schrecken*.", footnotes: ["℘ Jes 9,3"] },
      { number: 13, text: "Dann kehrte Gideon, der Sohn des Joasch, vom Kampf zurück, von der Anhöhe von Heres herab." },
      { number: 14, text: "Und er fing einen Jungen von den Männern von Sukkot und fragte ihn aus. Da schrieb der ihm die Obersten von Sukkot und seine Ältesten auf, 77 Mann." },
      { number: 15, text: "Und er kam zu den Männern von Sukkot und sagte: Seht hier Sebach und Zalmunna, mit denen ihr mich verhöhnt habt, als ihr sagtet: Ist die Faust Sebachs und Zalmunnas etwa schon in deiner Hand, dass wir deinen Männern, die ermattet sind, Brot geben sollten?" },
      { number: 16, text: "Und er nahm die Ältesten der Stadt und Dorngestrüpp der Wüste und Stechdisteln, und er züchtigte damit die Männer von Sukkot*.", footnotes: ["w. er gab es den Männern von Sukkot damit zu erkennen"] },
      { number: 17, text: "Und den Turm von Pnuël riss er nieder und erschlug die Männer der Stadt." },
      { number: 18, text: "Und er sagte zu Sebach und zu Zalmunna: Wie <sahen> die Männer <aus>, die ihr auf dem Tabor* erschlagen habt? Sie sagten: Ganz wie du, so waren sie, jeder gleich einem Königssohn.", footnotes: ["℘ Kap. 4,6.12"] },
      { number: 19, text: "Da sagte er: Meine Brüder, die Söhne meiner Mutter, waren sie. So wahr der HERR lebt, hättet ihr sie am Leben gelassen, würde ich euch nicht erschlagen*!", footnotes: ["℘ 4Mo 35,19"] },
      { number: 20, text: "Und er sagte zu Jeter, seinem Erstgeborenen: Steh auf, erschlag sie! Aber der Junge zog sein Schwert nicht; denn er fürchtete sich, weil er noch ein Junge war." },
      { number: 21, text: "Da sagten Sebach und Zalmunna: Steh du auf und stoß uns nieder! Denn wie der Mann, so seine Kraft. Da stand Gideon auf und erschlug Sebach und Zalmunna*. Und er nahm die Halbmonde*, die an den Hälsen ihrer Kamele <hingen>.", footnotes: ["℘ Jos 10,26; Ps 83,12", "℘ Jes 3,18"] },
      { number: 22, text: "Und die Männer von Israel sagten zu Gideon: Herrsche über uns*, sowohl du als auch dein Sohn und deines Sohnes Sohn! Denn du hast uns aus der Hand Midians gerettet.", heading: "Ablehnung der Königswürde — Das goldene Efod", footnotes: ["℘ 1Sam 8,5"] },
      { number: 23, text: "Gideon aber sagte zu ihnen: Nicht ich will über euch herrschen, auch mein Sohn soll nicht über euch herrschen. Der HERR soll über euch herrschen*.", footnotes: ["℘ 1Sam 12,12"] },
      { number: 24, text: "Und Gideon sagte zu ihnen: Eine Bitte will ich von euch erbitten: Gebt mir jeder einen Ring* von seiner Beute! (Denn sie hatten goldene Ringe, weil sie Ismaeliter waren*.)", footnotes: ["d. h. Ohrringe oder Nasenringe", "℘ 1Mo 25,12"] },
      { number: 25, text: "Sie sagten: Gern wollen wir <sie dir> geben. Und sie breiteten ein Obergewand aus und warfen darauf jeder einen Ring* von seiner Beute.", footnotes: ["d. h. Ohrringe oder Nasenringe"] },
      { number: 26, text: "Und das Gewicht der goldenen Ringe*, die er erbeten hatte, betrug 1 700 <Schekel> Gold, abgesehen von den Halbmonden und den Ohrgehängen und den Purpurkleidern, die die Könige von Midian getragen hatten, und abgesehen von den Halsketten, die an den Hälsen ihrer Kamele <gehangen hatten>.", footnotes: ["d. h. Ohrringe oder Nasenringe"] },
      { number: 27, text: "Und Gideon machte daraus ein Efod* und stellte es in seiner Stadt auf, in Ofra*. Und ganz Israel hurte ihm dort nach*. Das wurde Gideon und seinem Haus zur Falle*.", footnotes: ["℘ Kap. 17,5; 2Mo 32,4.8; Hes 7,20; Hos 3,4", "℘ V. 32; Kap. 6,24", "℘ 2Mo 34,16; Ps 106,35-39", "℘ Kap. 2,2.3; 5Mo 7,25"] },
      { number: 28, text: "So musste sich Midian vor den Söhnen Israel beugen und konnte sein Haupt nicht mehr erheben. Und das Land hatte in den Tagen Gideons vierzig Jahre Ruhe*.", heading: "Gideons Nachkommen und Tod", footnotes: ["℘ Kap. 3,11.30; 1Sam 7,13"] },
      { number: 29, text: "Und Jerubbaal, der Sohn des Joasch, ging hin und wohnte in seinem Haus." },
      { number: 30, text: "Und Gideon hatte siebzig Söhne, die <alle> aus seinem Schoß hervorgegangen waren*; denn er hatte viele Frauen.", footnotes: ["d. h. die <alle> von ihm abstammten\n℘ Kap. 9,2.5"] },
      { number: 31, text: "Und seine Nebenfrau, die in Sichem <wohnte>, auch sie gebar ihm einen Sohn; und er gab ihm den Namen Abimelech." },
      { number: 32, text: "Und Gideon, der Sohn des Joasch, starb in gutem Alter*. Und er wurde im Grab seines Vaters Joasch begraben, in Ofra<, der Stadt> der Abiësriter*.", footnotes: ["℘ 1Mo 25,8", "℘ V. 27"] },
      { number: 33, text: "Und es geschah, sobald Gideon gestorben war, da wandten sich die Söhne Israel <wieder> ab und hurten den Baalim nach* und machten sich den Baal-Berit* zum Gott*.", footnotes: ["℘ Kap. 2,17.19; 3,7; 10,6; 2Chr 24,17.18", "d. h. Bundes-Baal", "℘ Kap. 9,4.46"] },
      { number: 34, text: "Und die Söhne Israel dachten nicht mehr an den HERRN, ihren Gott, der sie der Hand all ihrer Feinde ringsum entrissen hatte*.", footnotes: ["℘ Ps 106,21; Jer 2,32; Hos 2,15"] },
      { number: 35, text: "Und sie erwiesen dem Haus Jerubbaal-Gideons keine Güte*, wie es all dem Guten, das er an Israel getan hatte, entsprochen hätte*.", footnotes: ["o. Dankbarkeit; o. Treue; o. Gnade", "℘ Kap. 9,16-19; 2Chr 24,22"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "Und Abimelech, der Sohn Jerubbaals, ging nach Sichem* zu den Brüdern seiner Mutter*. Und er redete zu ihnen und zur ganzen Sippe vom Haus des Vaters seiner Mutter und sagte:", heading: "Abimelechs Brudermord und Königtum", footnotes: ["℘ Jos 20,7", "℘ Kap. 8,30.31"] },
      { number: 2, text: "Redet doch vor den Ohren aller Bürger* von Sichem: Was ist besser für euch: dass siebzig Männer über euch herrschen, alle Söhne Jerubbaals*, oder dass <nur> ein Mann über euch herrscht? Und bedenkt, dass ich euer Gebein und euer Fleisch bin*!", footnotes: ["w. <Grund>besitzer, o. Herren", "℘ Kap. 8,30.31", "℘ 1Mo 29,14"] },
      { number: 3, text: "Da redeten die Brüder seiner Mutter über ihn vor den Ohren aller Bürger* von Sichem all diese Worte. Und ihr Herz neigte sich Abimelech zu*, denn sie sagten <sich>: Er ist unser Bruder.", footnotes: ["w. <Grund>besitzer, o. Herren", "℘ 2Sam 15,13"] },
      { number: 4, text: "Und sie gaben ihm siebzig <Schekel> Silber aus dem Haus des Baal-Berit*. Und Abimelech kaufte sich damit ehrlose und leichtfertige Männer; die folgten ihm nach*.", footnotes: ["d. h. Bundes-Baal\n℘ V. 27; Kap. 8,33", "℘ Kap. 11,3; 2Chr 13,7; Apg 17,5"] },
      { number: 5, text: "Und er kam in das Haus seines Vaters, nach Ofra*, und erschlug seine Brüder*, die Söhne Jerubbaals, siebzig Mann auf einem Stein. Es blieb aber Jotam übrig, der jüngste Sohn Jerubbaals, denn er hatte sich versteckt*.", footnotes: ["℘ Kap. 6,11.24", "℘ 1Kö 1,21; 2Chr 21,4", "℘ 2Kö 11,3"] },
      { number: 6, text: "Und alle Bürger* von Sichem und die ganze Bewohnerschaft des Millo* versammelten sich und gingen hin und machten Abimelech zum König bei der Denkmals-Terebinthe*, die in Sichem <steht>*.", footnotes: ["w. <Grund>besitzer, o. Herren", "w. das ganze Haus Millo; Millo (w. Aufschüttung) ist eine Befestigungsanlage\n℘ 2Sam 5,9", "Manche nehmen an, dass es ursprünglich hieß: bei der Mazzeba-Terebinthe", "℘ Jos 24,26"] },
      { number: 7, text: "Und man berichtete es Jotam. Da ging er hin und stellte sich auf den Gipfel des Berges Garizim*, und er erhob seine Stimme, rief und sagte zu ihnen: Hört auf mich, Bürger* von Sichem, dann wird Gott auf euch hören!", heading: "Jotams Fabel und Rede gegen Abimelech", footnotes: ["℘ 5Mo 27,12", "w. <Grund>besitzer, o. Herren"] },
      { number: 8, text: "Einst gingen die Bäume hin, einen König über sich zu salben. Und sie sagten zum Olivenbaum: Sei König über uns!" },
      { number: 9, text: "Da sagte ihnen der Olivenbaum: Sollte ich meine Fettigkeit aufgeben, die Götter und Menschen an mir in Ehren halten*, und sollte ich hingehen, um über den Bäumen zu schweben?", footnotes: ["℘ Ps 104,15"] },
      { number: 10, text: "Und die Bäume sagten zum Feigenbaum: Komm du, sei König über uns!" },
      { number: 11, text: "Da sagte ihnen der Feigenbaum: Sollte ich meine Süßigkeit aufgeben und meine gute Frucht, und sollte ich hingehen, um über den Bäumen zu schweben?" },
      { number: 12, text: "Und die Bäume sagten zum Weinstock: Komm du, sei König über uns!" },
      { number: 13, text: "Da sagte ihnen der Weinstock: Sollte ich meinen Most aufgeben, der Götter und Menschen erfreut*, und sollte ich hingehen, um über den Bäumen zu schweben?", footnotes: ["℘ Ps 104,15"] },
      { number: 14, text: "Und alle Bäume sagten zum Dornstrauch*: Komm du, sei König über uns!", footnotes: ["℘ 2Kö 14,9"] },
      { number: 15, text: "Da sagte der Dornstrauch zu den Bäumen: Wollt ihr in Wahrheit* mich zum König über euch salben, so kommt, sucht Zuflucht in meinem Schatten*! Wenn aber nicht, so gehe Feuer aus vom Dornstrauch*, das fresse die Zedern des Libanon! —", footnotes: ["o. Treue", "℘ Kla 4,20", "℘ 4Mo 21,28; Hes 19,14"] },
      { number: 16, text: "Und nun, wenn ihr in Wahrheit* und Aufrichtigkeit gehandelt habt, als ihr Abimelech zum König gemacht habt, und wenn ihr Gutes getan habt an Jerubbaal und an seinem Haus und wenn ihr ihm getan habt nach dem Tun seiner Hände* —", footnotes: ["o. Treue", "℘ Kap. 8,35"] },
      { number: 17, text: "denn mein Vater hat für euch gekämpft und sein Leben eingesetzt* und euch der Hand Midians entrissen;", footnotes: ["w. seine Seele von <sich> geworfen\n℘ Kap. 12,3"] },
      { number: 18, text: "ihr aber habt euch heute gegen das Haus meines Vaters erhoben und seine Söhne erschlagen, siebzig Mann auf einem Stein, und habt Abimelech, den Sohn seiner Sklavin, zum König gemacht über die Bürger* von Sichem, weil er euer Bruder ist —,", footnotes: ["w. <Grund>besitzer, o. Herren"] },
      { number: 19, text: "wenn ihr also an diesem Tag in Wahrheit* und Aufrichtigkeit an Jerubbaal und an seinem Haus gehandelt habt, dann habt eure Freude an Abimelech, und auch er soll seine Freude an euch haben!", footnotes: ["o. Treue"] },
      { number: 20, text: "Wenn aber nicht, so gehe Feuer von Abimelech aus und fresse die Bürger* von Sichem und die Bewohnerschaft des Millo*! Und es gehe Feuer aus von den Bürgern* von Sichem und von der Bewohnerschaft des Millo* und fresse Abimelech*!", footnotes: ["w. <Grund>besitzer, o. Herren", "w. das ganze Haus Millo; Millo (w. Aufschüttung) ist eine Befestigungsanlage", "w. das ganze Haus Millo; Millo (w. Aufschüttung) ist eine Befestigungsanlage", "w. das ganze Haus Millo; Millo (w. Aufschüttung) ist eine Befestigungsanlage", "℘ V. 15.45-49.57"] },
      { number: 21, text: "Und Jotam floh und entwich und ging nach Beer* und blieb dort wohnen <aus Furcht> vor seinem Bruder Abimelech.", footnotes: ["℘ 4Mo 21,16"] },
      { number: 22, text: "Und Abimelech herrschte über Israel drei Jahre.", heading: "Abimelechs Ende" },
      { number: 23, text: "Da sandte Gott einen bösen Geist* zwischen Abimelech und die Bürger* von Sichem. Und die Bürger* von Sichem handelten treulos an Abimelech,", footnotes: ["℘ 1Sam 16,14; 1Kö 22,23", "w. <Grund>besitzer, o. Herren", "w. <Grund>besitzer, o. Herren"] },
      { number: 24, text: "damit die Gewalttat an den siebzig Söhnen Jerubbaals <auf ihn> zurückkäme und ihr Blut auf ihren Bruder Abimelech gelegt würde, der sie erschlagen hatte, und auf die Bürger* von Sichem, die seine Hände gestärkt hatten, seine Brüder zu erschlagen*.", footnotes: ["w. <Grund>besitzer, o. Herren", "℘ Kap. 1,7; 1Kö 2,32; Ps 7,17"] },
      { number: 25, text: "Und die Bürger* von Sichem legten <Wegelagerer in> einen Hinterhalt gegen ihn auf den Höhen der Berge; die beraubten jeden, der an ihnen auf dem Weg vorüberzog*. Das wurde dem Abimelech berichtet.", footnotes: ["w. <Grund>besitzer, o. Herren", "℘ Ps 10,8-10"] },
      { number: 26, text: "Und Gaal, der Sohn Ebeds, kam mit seinen Brüdern, und sie zogen durch Sichem. Und die Bürger* von Sichem vertrauten ihm.", footnotes: ["w. <Grund>besitzer, o. Herren"] },
      { number: 27, text: "Und sie gingen aufs Feld hinaus und hielten Lese in ihren Weinbergen und kelterten. Und sie hielten ein Freudenfest und gingen in das Haus ihres Gottes*, aßen und tranken und fluchten dem Abimelech.", footnotes: ["℘ V. 4"] },
      { number: 28, text: "Und Gaal, der Sohn Ebeds, sagte: Wer ist Abimelech und wer Sichem, dass wir <ihm> dienen sollten*? Ist er nicht der Sohn Jerubbaals und Sebul sein Statthalter? Dient <lieber> den Männern Hamors, des Vaters von Sichem*! Warum sollten gerade wir ihm dienen?", footnotes: ["℘ 1Sam 25,10; 1Kö 12,16", "℘ 1Mo 33,19"] },
      { number: 29, text: "Hätte ich nur dieses Volk unter meiner Hand*, so wollte ich Abimelech <schon> beseitigen, und ich würde zu Abimelech sagen*: Vermehre <doch> dein Heer und zieh aus*!", footnotes: ["℘ 2Sam 15,4", "so mit LXX; Mas. T.: und er sagte zu Abimelech", "℘ 2Kö 14,8; Jak 4,16"] },
      { number: 30, text: "Als nun Sebul, der Oberste der Stadt, die Worte Gaals, des Sohnes Ebeds, hörte, da entbrannte sein Zorn." },
      { number: 31, text: "Und er sandte Boten zu Abimelech mit List* und <ließ ihm> sagen: Siehe, Gaal, der Sohn Ebeds, und seine Brüder sind nach Sichem gekommen, und siehe, sie wiegeln die Stadt gegen dich auf.", footnotes: ["Manche üs. mit Textänderung: zu Abimelech nach Aruma"] },
      { number: 32, text: "Und nun, mache dich in der Nacht auf, du und das <Kriegs>volk, das bei dir ist, und lege dich auf dem Feld in einen Hinterhalt*!", footnotes: ["℘ Jos 8,3.4"] },
      { number: 33, text: "Und es geschehe am Morgen, wenn die Sonne aufgeht, dann mache dich früh auf und überfalle die Stadt! Siehe, wenn er und das <Kriegs>volk, das bei ihm ist, gegen dich herausziehen, dann tu ihm, wie deine Hand es finden wird*!", footnotes: ["d. h. das, wozu du in der Lage bist"] },
      { number: 34, text: "Da machten sich Abimelech und das ganze <Kriegs>volk, das bei ihm war, in der Nacht auf und legten sich in vier Abteilungen gegen Sichem in einen Hinterhalt." },
      { number: 35, text: "Und Gaal, der Sohn Ebeds, ging hinaus und trat an den Eingang des Stadttores. Da machten sich Abimelech und das <Kriegs>volk, das bei ihm war, aus dem Hinterhalt auf." },
      { number: 36, text: "Als nun Gaal das <Kriegs>volk sah, sagte er zu Sebul: Siehe, <Kriegs>volk kommt von den Höhen der Berge herab. Sebul aber sagte zu ihm: Den Schatten der Berge siehst du als Männer an." },
      { number: 37, text: "Doch Gaal beharrte darauf* und sagte: Sieh doch, <Kriegs>volk kommt von der Höhe des Landes* herab, und eine Abteilung kommt aus der Richtung von Elon-Meonenim*.", footnotes: ["w. fuhr fort weiterzureden", "w. vom Nabel des Landes, o. der Erde; wahrscheinlich eine Bezeichnung des Berges Garizim als eines heiligen Ortes", "d. h. Terebinthe der Zauberer"] },
      { number: 38, text: "Da sagte Sebul zu ihm: Wo ist nun dein Maul, mit dem du sagtest: Wer ist Abimelech, dass wir ihm dienen sollten? Ist das nicht das <Kriegs>volk, das du verachtet hast*? Zieh doch jetzt aus und kämpfe mit ihm!", footnotes: ["℘ 1Sam 2,3"] },
      { number: 39, text: "Da zog Gaal hinaus, vor den Bürgern* von Sichem her, und kämpfte mit Abimelech.", footnotes: ["w. den <Grund>besitzern, o. den Herren"] },
      { number: 40, text: "Und Abimelech jagte ihn, so dass er vor ihm floh. Und viele fielen <und lagen> erschlagen bis an den Eingang des Tores." },
      { number: 41, text: "Und Abimelech blieb in Aruma. Sebul aber vertrieb Gaal und seine Brüder, so dass sie nicht mehr in Sichem blieben." },
      { number: 42, text: "Und es geschah am andern Tag, da ging das Volk aufs Feld hinaus. Das berichtete man Abimelech." },
      { number: 43, text: "Da nahm er das <Kriegs>volk und teilte es in drei Abteilungen und legte sich auf dem Feld in einen Hinterhalt. Und er sah, und siehe, das Volk kam aus der Stadt heraus. Da erhob er sich gegen sie und schlug sie." },
      { number: 44, text: "Und Abimelech und die Abteilungen, die bei ihm waren, brachen hervor und stellten sich an den Eingang des Stadttores. Die beiden <anderen> Abteilungen aber fielen über alle her, die auf dem Feld waren, und erschlugen sie." },
      { number: 45, text: "Und Abimelech kämpfte jenen ganzen Tag gegen die Stadt. Und er nahm die Stadt ein, und das Volk, das darin war, erschlug er. Und er riss die Stadt nieder* und bestreute sie mit Salz*.", footnotes: ["℘ 2Kö 3,25", "als Zeichen bleibender Verwüstung"] },
      { number: 46, text: "Als das alle Bürger von Migdal-Sichem* hörten, gingen sie in das Kellergewölbe des Hauses des Gottes Berit*.", footnotes: ["o. alle Herren des Turms von Sichem", "o. des Bundesgottes; vgl. Kap. 8,33\n℘ Kap. 8,33"] },
      { number: 47, text: "Und es wurde dem Abimelech berichtet, dass alle Bürger von Migdal-Sichem* sich versammelt hätten.", footnotes: ["o. alle Herren des Turms von Sichem"] },
      { number: 48, text: "Da stieg Abimelech auf den Berg Zalmon*, er und das ganze <Kriegs>volk, das bei ihm war. Und Abimelech nahm eine Axt* in seine Hand und hieb einen Ast vom Baum ab, hob ihn auf und legte ihn auf seine Schulter. Und er sagte zu dem Volk, das bei ihm war: Was ihr mich habt tun sehen, schnell, macht es wie ich!", footnotes: ["℘ Ps 68,15", "w. die Äxte"] },
      { number: 49, text: "Da hieb auch das ganze Volk, jeder seinen Ast ab, und sie folgten Abimelech, legten <alles> auf das Kellergewölbe und steckten das Kellergewölbe über ihnen in Brand. So starben auch alle Leute von Migdal-Sichem, etwa tausend Männer und Frauen." },
      { number: 50, text: "Dann zog Abimelech nach Tebez und belagerte Tebez und nahm es ein." },
      { number: 51, text: "Es war aber ein starker Turm mitten in der Stadt, und dahin flohen alle Männer und Frauen, alle Bürger* der Stadt. Und sie schlossen hinter sich zu und stiegen auf das Dach des Turmes.", footnotes: ["w. <Grund>besitzer, o. Herren"] },
      { number: 52, text: "Und Abimelech kam an den Turm und kämpfte gegen ihn. Und er trat an den Eingang des Turmes, um ihn mit Feuer zu verbrennen." },
      { number: 53, text: "Da warf eine Frau einen oberen Mühlstein auf Abimelechs Kopf und zerschmetterte ihm den Schädel*.", footnotes: ["℘ 2Sam 11,21; Hi 31,3"] },
      { number: 54, text: "Da rief er schnell nach dem Burschen, seinem Waffenträger, und sagte zu ihm: Zieh dein Schwert und töte mich, damit man nicht von mir sagt: Eine Frau hat ihn erschlagen*! Und sein Bursche durchbohrte ihn, dass er starb.", footnotes: ["℘ Kap. 4,9; 1Sam 31,4; 2Sam 1,9"] },
      { number: 55, text: "Und als die Männer von Israel sahen, dass Abimelech tot war, da gingen sie, jeder an seinen Ort." },
      { number: 56, text: "So ließ Gott die Bosheit Abimelechs, die er an seinem Vater verübt hatte, indem er seine siebzig Brüder erschlug, <auf ihn> zurückkommen." },
      { number: 57, text: "Und die ganze Bosheit der Männer von Sichem ließ Gott auf ihren Kopf zurückkommen*. So kam über sie der Fluch Jotams, des Sohnes Jerubbaals*.", footnotes: ["℘ Kap. 1,7; 2Sam 3,39; Ps 7,17; 94,23; Spr 5,22.23; Jes 3,11", "℘ V. 20"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "*Und nach Abimelech stand auf, um Israel zu retten, Tola, der Sohn des Puwa, des Sohnes des Dodo, ein Mann aus Issaschar*. Er wohnte in Schamir im Gebirge Ephraim*.", heading: "Die Richter Tola und Jaïr", footnotes: ["℘ vgl. Kap. 12,8-15", "℘ Kap. 2,16", "℘ Kap. 3,27"] },
      { number: 2, text: "Und er richtete Israel 23 Jahre. Und er starb und wurde in Schamir begraben." },
      { number: 3, text: "Und nach ihm stand Jaïr auf, der Gileaditer. Er richtete Israel 22 Jahre." },
      { number: 4, text: "Und er hatte dreißig Söhne, die auf dreißig Eseln ritten*, und sie hatten dreißig Städte. Diese nennt man die Zeltdörfer Jaïrs* bis auf diesen Tag; sie <liegen> im Land Gilead.", footnotes: ["℘ Kap. 5,10", "℘ 4Mo 32,41"] },
      { number: 5, text: "Und Jaïr starb und wurde in Kamon begraben." },
      { number: 6, text: "Und die Söhne Israel taten weiter, was böse war in den Augen des HERRN, und sie dienten den Baalim und den Astarot und den Göttern Arams und den Göttern Sidons und den Göttern Moabs und den Göttern der Söhne Ammon und den Göttern der Philister*. Und sie verließen den HERRN und dienten ihm nicht*.", heading: "Unterdrückung der Israeliten durch Ammon", footnotes: ["℘ Kap. 8,33; 5Mo 13,6", "℘ Kap. 2,11.13; 1Kö 11,5; Jer 2,20"] },
      { number: 7, text: "Da entbrannte der Zorn des HERRN gegen Israel, und er verkaufte sie in die Hand der Philister* und in die Hand der Söhne Ammon*.", footnotes: ["℘ Kap. 2,14; 13,1; 1Sam 12,9", "℘ Kap. 6,1"] },
      { number: 8, text: "Und sie zerschmetterten und zerschlugen die Söhne Israel in jenem Jahr, <und zwar> achtzehn Jahre <lang> alle Söhne Israel, die jenseits des Jordan waren im Land der Amoriter, das in Gilead ist*.", footnotes: ["℘ 4Mo 32,39"] },
      { number: 9, text: "Und die Söhne Ammon* zogen über den Jordan, um auch gegen Juda und gegen Benjamin und gegen das Haus Ephraim zu kämpfen. So war Israel in großer Bedrängnis*.", footnotes: ["℘ Kap. 3,13", "℘ Kap. 2,15; 6,2-6; 1Sam 13,6"] },
      { number: 10, text: "Da schrien die Söhne Israel zu dem HERRN um Hilfe* und sagten: Wir haben gegen dich gesündigt, weil wir unseren Gott verlassen und den Baalim gedient haben*.", footnotes: ["℘ Kap. 4,3; 6,6", "℘ 1Sam 7,6; Lk 15,17.18"] },
      { number: 11, text: "Und der HERR sprach zu den Söhnen Israel: Ist es nicht so? Von den Ägyptern* und von den Amoritern*, von den Söhnen Ammon und von den Philistern*,", footnotes: ["℘ 2Mo 14,30", "℘ 4Mo 21,24", "℘ Kap. 3,28-31"] },
      { number: 12, text: "und als die Sidonier und Amalekiter* und Maoniter* euch quälten* und als ihr da zu mir schriet, da habe ich euch aus ihrer Hand gerettet*.", footnotes: ["℘ Kap. 3,13; 6,3", "LXX: Midianiter\n℘ 1Chr 4,41", "w. euch verdrängen wollten", "℘ Ps 106,43"] },
      { number: 13, text: "Ihr aber, ihr habt mich verlassen und habt andern Göttern gedient*. Darum werde ich nicht fortfahren, euch zu retten*.", footnotes: ["℘ Kap. 2,19; 2Chr 15,2; Jer 2,13.19", "℘ 2Chr 12,5; 21,10"] },
      { number: 14, text: "Geht hin und schreit zu den Göttern um Hilfe, die ihr erwählt habt! Sollen sie euch doch retten zur Zeit eurer Not*!", footnotes: ["℘ 5Mo 32,38; 2Kö 3,13; Jes 46,7; 57,13; Jer 2,28; Hes 20,39"] },
      { number: 15, text: "Da sagten die Söhne Israel zu dem HERRN: Wir haben gesündigt*. Tu du uns nach allem, was gut ist in deinen Augen*! Nur rette uns doch am heutigen Tag*!", footnotes: ["℘ 1Sam 7,6; Lk 15,17.18", "℘ 1Sam 3,18; Spr 28,13", "℘ Jes 26,16"] },
      { number: 16, text: "Und sie entfernten die fremden Götter aus ihrer Mitte und dienten dem HERRN*. Da wurde seine Seele ungeduldig über das Elend Israels*.", footnotes: ["℘ 1Sam 7,4; 12,10; 2Chr 15,8", "℘ Kap. 2,18; 2Kö 13,23; Ps 106,45; Jer 31,20; Mi 7,18"] },
      { number: 17, text: "Und die Söhne Ammon wurden zusammengerufen und lagerten in Gilead. Und die Söhne Israel versammelten sich und lagerten in Mizpa*.", footnotes: ["℘ Kap. 11,29; 1Mo 31,49; Jos 13,26"] },
      { number: 18, text: "Da sagte das Volk, <nämlich> die Obersten von Gilead, einer zum andern: Wer ist der Mann, der anfängt, mit den Söhnen Ammon zu kämpfen? Er soll das Oberhaupt aller Bewohner Gileads werden*.", footnotes: ["℘ Kap. 11,4-11"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "Und Jeftah, der Gileaditer, war ein tapferer Held*. Er war aber der Sohn einer Hure, und Gilead hatte Jeftah gezeugt.", heading: "Jeftahs Berufung", footnotes: ["℘ Kap. 6,12; 1Sam 12,11; Hebr 11,32"] },
      { number: 2, text: "Aber <auch> Gileads Frau hatte ihm Söhne geboren. Als nun die Söhne der Frau groß geworden waren, vertrieben sie Jeftah und sagten zu ihm: Du erbst nicht mit dem Haus unseres Vaters, denn du bist der Sohn einer anderen Frau*.", footnotes: ["℘ 1Mo 21,10"] },
      { number: 3, text: "So war Jeftah vor seinen Brüdern geflohen und hatte sich im Land Tob* niedergelassen. Und es sammelten sich bei Jeftah ehrlose Leute, die zogen mit ihm aus*.", footnotes: ["℘ 2Sam 10,6.8", "℘ Kap. 9,4"] },
      { number: 4, text: "Und es geschah nach einiger Zeit, da kämpften die Söhne Ammon mit Israel*.", footnotes: ["℘ 1Sam 11,1"] },
      { number: 5, text: "Und es geschah, als die Söhne Ammon mit Israel kämpften, da gingen die Ältesten von Gilead hin, um Jeftah aus dem Land Tob* zu holen.", footnotes: ["℘ 2Sam 10,6.8"] },
      { number: 6, text: "Und sie sagten zu Jeftah: Komm und sei unser Anführer*, damit wir gegen die Söhne Ammon kämpfen können!", footnotes: ["℘ Kap. 10,17.18"] },
      { number: 7, text: "Da sagte Jeftah zu den Ältesten von Gilead: Seid ihr es nicht gewesen, die mich gehasst und mich aus dem Haus meines Vaters vertrieben haben? Und warum kommt ihr jetzt zu mir, da ihr in Bedrängnis seid*?", footnotes: ["℘ 1Mo 26,27"] },
      { number: 8, text: "Und die Ältesten von Gilead sagten zu Jeftah: Darum sind wir jetzt zu dir zurückgekehrt, damit du mit uns ziehst und gegen die Söhne Ammon kämpfst. Du sollst unser Oberhaupt werden für alle Bewohner Gileads." },
      { number: 9, text: "Da sagte Jeftah zu den Ältesten von Gilead: Wenn ihr mich zurückholt zum Kampf gegen die Söhne Ammon und der HERR sie vor mir dahingibt, werde ich <dann> wirklich euer Oberhaupt sein?" },
      { number: 10, text: "Und die Ältesten von Gilead sagten zu Jeftah: Der HERR sei Zeuge* zwischen uns: Wenn wir nicht so tun, wie du geredet hast*!*", footnotes: ["w. Hörer", "℘ 1Mo 31,50; Jer 42,5", "Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde."] },
      { number: 11, text: "Da ging Jeftah mit den Ältesten von Gilead mit, und das Volk setzte ihn als Oberhaupt und als Anführer über sich. Und Jeftah redete alle seine Worte* vor dem HERRN in Mizpa.", footnotes: ["d. h. Jeftah wiederholte alle seine Bedingungen"] },
      { number: 12, text: "Und Jeftah sandte Boten an den König der Söhne Ammon und <ließ ihm> sagen: Was habe ich mit dir <zu tun>, dass du gegen mich gekommen bist, um gegen mein Land Krieg zu führen*?", heading: "Jeftahs Verhandlung mit den Ammonitern", footnotes: ["℘ 5Mo 20,10"] },
      { number: 13, text: "Und der König der Söhne Ammon sagte zu den Boten Jeftahs: Weil Israel, als es aus Ägypten heraufzog, mein Land genommen hat, vom Arnon bis an den Jabbok* und bis an den Jordan. Und nun gib die Länder* in Frieden zurück!", footnotes: ["℘ 4Mo 21,24-26", "w. sie"] },
      { number: 14, text: "Da sandte Jeftah noch einmal Boten an den König der Söhne Ammon" },
      { number: 15, text: "und ließ ihm sagen: So spricht Jeftah: Israel hat nicht das Land Moabs und das Land der Söhne Ammon genommen*.", footnotes: ["℘ 5Mo 2,9.19"] },
      { number: 16, text: "Sondern als sie aus Ägypten heraufzogen, da wanderte Israel durch die Wüste bis zum Schilfmeer*, und es kam nach Kadesch*.", footnotes: ["℘ 4Mo 14,25", "℘ 5Mo 1,46"] },
      { number: 17, text: "Und Israel sandte Boten an den König von Edom und <ließ ihm> sagen: Lass mich doch durch dein Land ziehen! Aber der König von Edom hörte nicht <darauf>*. Und auch an den König von Moab sandte es; aber <auch der> wollte nicht. So blieb Israel in Kadesch*.", footnotes: ["℘ 4Mo 20,14-21", "℘ 5Mo 1,46"] },
      { number: 18, text: "Und es wanderte durch die Wüste und umging das Land Edom und das Land Moab und kam von Sonnenaufgang her zum Land Moab. Und sie lagerten jenseits des Arnon und kamen nicht in das Gebiet Moabs, denn der Arnon ist die Grenze Moabs*.", footnotes: ["℘ 4Mo 21,13"] },
      { number: 19, text: "*Und Israel sandte Boten an Sihon, den König der Amoriter, den König von Heschbon, und Israel ließ ihm sagen: Lass uns doch durch dein Land ziehen bis an meinen Ort!", footnotes: ["℘ V. 19-22: 4Mo 21,21-25"] },
      { number: 20, text: "Aber Sihon traute Israel nicht, dass es <nur> durch sein Gebiet hindurchziehen wolle. Und Sihon versammelte sein ganzes <Kriegs>volk, und sie lagerten sich in Jahaz; und er kämpfte gegen Israel." },
      { number: 21, text: "Da gab der HERR, der Gott Israels, den Sihon und sein ganzes <Kriegs>volk in die Hand Israels, und sie schlugen sie. So nahm Israel das ganze Land der Amoriter, die jenes Land bewohnten, in Besitz:" },
      { number: 22, text: "Sie nahmen das ganze Gebiet der Amoriter in Besitz, vom Arnon bis an den Jabbok und von der Wüste bis an den Jordan." },
      { number: 23, text: "Und nun: Der HERR, der Gott Israels, hat die Amoriter vor seinem Volk Israel vertrieben, da willst du uns <wieder> daraus verdrängen*?", footnotes: ["o. da willst du es von uns <wieder> in Besitz nehmen"] },
      { number: 24, text: "Ist es nicht <so>: Wen Kemosch*, dein Gott, <vor> dir vertreibt, dessen Land* nimmst du in Besitz. Und wen immer der HERR, unser Gott, vor uns her vertreibt, dessen Land* nehmen wir in Besitz*.", footnotes: ["℘ 4Mo 21,29; 1Kö 11,7; Jer 48,7.46", "w. den", "w. den", "℘ Kap. 2,1; Jos 21,43"] },
      { number: 25, text: "Und nun, bist du wirklich besser als Balak, der Sohn Zippors, der König von Moab*? Hat er sich etwa in einen Rechtsstreit mit Israel eingelassen oder jemals mit ihnen einen Krieg angefangen?", footnotes: ["℘ 4Mo 22,2"] },
      { number: 26, text: "Während Israel in Heschbon* wohnte und in seinen Tochterstädten und in Aroër* und in seinen Tochterstädten und in all den Städten, die längs des Arnon <liegen>, dreihundert Jahre lang — warum habt ihr <sie uns> denn nicht in jener Zeit entrissen?", footnotes: ["℘ Jos 13,17", "℘ 5Mo 2,36; Jer 48,19"] },
      { number: 27, text: "Nicht ich habe gegen dich gesündigt, sondern du tust mir Böses an, indem du gegen mich Krieg führst. Es richte der HERR, der Richter, heute zwischen den Söhnen Israel und den Söhnen Ammon*!", footnotes: ["℘ 1Mo 16,5; 1Sam 24,13"] },
      { number: 28, text: "Aber der König der Söhne Ammon hörte nicht auf Jeftahs Worte, die er zu ihm gesandt hatte.", heading: "Jeftahs Gelübde und Sieg" },
      { number: 29, text: "Da kam der Geist des HERRN über Jeftah*. Und er zog durch Gilead und Manasse und zog nach Mizpa in Gilead, und von Mizpa in Gilead zog er weiter zu den Söhnen Ammon*.", footnotes: ["℘ Kap. 3,10", "℘ Kap. 10,17"] },
      { number: 30, text: "Und Jeftah gelobte dem HERRN ein Gelübde* und sagte: Wenn du die Söhne Ammon wirklich in meine Hand gibst,", footnotes: ["℘ 1Mo 28,20"] },
      { number: 31, text: "dann soll der — wer es auch sei —, der aus der Tür meines Hauses herauskommt* mir entgegen, wenn ich in Frieden* von den Söhnen Ammon zurückkehre, der soll dem HERRN gehören; ich will ihn als Brandopfer opfern!", footnotes: ["w. dann soll der Herauskommende, der herauskommt aus der Tür meines Hauses", "o. wohlbehalten; o. unversehrt"] },
      { number: 32, text: "So zog Jeftah zu den Söhnen Ammon hinüber, um gegen sie zu kämpfen. Und der HERR gab sie in seine Hand*.", footnotes: ["℘ Kap. 2,16"] },
      { number: 33, text: "Und er schlug sie von Aroër an* bis dahin, wo man nach Minnit* kommt, zwanzig Städte, und bis nach Abel-Keramim — eine sehr große Niederlage <für die Söhne Ammon>*. So mussten sich die Söhne Ammon vor den Söhnen Israel beugen*.", footnotes: ["℘ 4Mo 32,34", "℘ Hes 27,17", "℘ 1Kö 20,21", "o. So wurden die Söhne Ammon von den Söhnen Israel gedemütigt"] },
      { number: 34, text: "Und Jeftah kam nach Mizpa* zu seinem Haus. Und siehe, da trat seine Tochter heraus ihm entgegen, mit Tamburinen und in Reigentänzen*. Nur sie hatte er, als Einzige; außer ihr* hatte er weder Sohn noch Tochter.", footnotes: ["℘ Kap. 20,1; Jos 18,26", "℘ Kap. 21,21; 2Mo 15,20", "so mit LXX; Mas. T.: außer ihm"] },
      { number: 35, text: "Und es geschah, als er sie sah, da zerriss er seine Kleider* und sagte: Wehe, meine Tochter! Tief beugst du mich nieder. Du, du bist unter denen, die mich ins Unglück bringen! Ich selber habe meinen Mund gegen den HERRN aufgerissen und kann nicht mehr zurück*!", footnotes: ["℘ 1Mo 37,29.34; 4Mo 14,6; Jos 7,6", "℘ 4Mo 30,3; 1Sam 14,44; Ps 66,13.14"] },
      { number: 36, text: "Da sagte sie zu ihm: Mein Vater, hast du deinen Mund gegen den HERRN aufgerissen, so tu mir, wie es aus deinem Mund hervorgegangen ist, nachdem der HERR dir Rache verschafft hat an deinen Feinden, den Söhnen Ammon!" },
      { number: 37, text: "Und sie sagte <weiter> zu ihrem Vater: Es möge dies mir gewährt* werden: Lass mir* zwei Monate, dass ich hingehe und hinabsteige über die Berge und meine Jungfrauschaft beweine, ich und meine Freundinnen!", footnotes: ["w. getan", "w. Lass ab von mir"] },
      { number: 38, text: "Er sagte: Geh hin! Und er entließ sie für zwei Monate. So ging sie hin, sie und ihre Freundinnen, und beweinte ihre Jungfrauschaft auf den Bergen." },
      { number: 39, text: "Und es geschah am Ende von zwei Monaten, da kehrte sie zu ihrem Vater zurück. Und er vollzog an ihr sein Gelübde, das er gelobt hatte. Sie hatte aber keinen Mann erkannt. Und es wurde zur Ordnung in Israel:" },
      { number: 40, text: "Von Jahr zu Jahr gehen die Töchter Israel hin, um die Tochter Jeftahs, des Gileaditers, zu besingen, vier Tage im Jahr*.", footnotes: ["℘ 2Chr 35,25; Est 9,27"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "Und die Männer von Ephraim wurden zusammengerufen und zogen hinüber nach Norden. Und sie sagten zu Jeftah: Warum bist du hinübergezogen, um gegen die Söhne Ammon zu kämpfen, und hast uns nicht gerufen, mit dir zu gehen*? Wir werden dein Haus über dir mit Feuer verbrennen*!", heading: "Jeftahs Sieg über die Ephraimiter", footnotes: ["℘ Kap. 8,1", "℘ Kap. 14,15; 15,6"] },
      { number: 2, text: "Da sagte Jeftah zu ihnen: Ich habe einen heftigen Streit ausgefochten*, ich und mein Volk, mit den Söhnen Ammon. Ich habe euch zu Hilfe gerufen, aber ihr habt mich nicht aus ihrer Hand gerettet.", footnotes: ["w. Ein Mann des Rechtsstreites bin ich gewesen"] },
      { number: 3, text: "Und als ich sah, dass du als Retter nicht da warst, legte ich mein Leben in meine <eigene> Hand* und zog hin gegen die Söhne Ammon. Und der HERR gab sie in meine Hand. Was seid ihr denn an diesem Tag gegen mich heraufgezogen, um gegen mich zu kämpfen?", footnotes: ["℘ Kap. 9,17; 1Sam 19,5"] },
      { number: 4, text: "Und Jeftah versammelte alle Männer von Gilead und kämpfte mit Ephraim. Und die Männer von Gilead schlugen Ephraim; denn die hatten gesagt: Flüchtlinge von Ephraim seid ihr! Gilead <liegt doch> mitten in Ephraim, mitten in Manasse!" },
      { number: 5, text: "Und Gilead nahm Ephraim die Furten des Jordan*. Und es geschah, wenn ephraimitische Flüchtlinge sagten: Lass mich hinübergehen!, dann sagten die Männer von Gilead zu ihm: Bist du ein Ephraimiter*? Und sagte er: Nein!,", footnotes: ["o. besetzte die Furten des Jordan<, die> nach Ephraim <führen>\n℘ Kap. 3,28", "w. ein Efratiter\n℘ Kap. 17,7; 1Sam 1,1; 1Kö 11,26"] },
      { number: 6, text: "so sprachen sie zu ihm: Sag mal: Schibbolet*! Und sagte er: Sibbolet!, und brachte es nicht fertig, richtig zu sprechen*, dann packten sie ihn und schlachteten ihn an den Furten des Jordan. So fielen in jener Zeit von Ephraim 42 000 <Mann>.", footnotes: ["d. h. Strömung", "℘ Mt 26,73"] },
      { number: 7, text: "Und Jeftah richtete Israel sechs Jahre. Und Jeftah, der Gileaditer, starb und wurde in einer der Städte Gileads* begraben.", footnotes: ["LXX: in seiner Stadt in Gilead"] },
      { number: 8, text: "*Und nach ihm richtete Israel Ibzan von Bethlehem*.", heading: "Die Richter Ibzan, Elon und Abdon", footnotes: ["℘ vgl. Kap. 10,1-5", "℘ Kap. 17,7; 19,1; Jos 19,15.16"] },
      { number: 9, text: "Und er hatte dreißig Söhne*. Dreißig Töchter entließ er nach auswärts, und dreißig Töchter holte er von auswärts für seine Söhne herein. Und er richtete Israel sieben Jahre.", footnotes: ["℘ Ps 127,3-5"] },
      { number: 10, text: "Und Ibzan starb und wurde in Bethlehem begraben." },
      { number: 11, text: "Und nach ihm richtete Israel Elon, der Sebuloniter. Er richtete Israel zehn Jahre." },
      { number: 12, text: "Und Elon, der Sebuloniter, starb und wurde in Ajalon im Land Sebulon begraben." },
      { number: 13, text: "Und nach ihm richtete Israel Abdon, der Sohn Hillels, der Piratoniter*.", footnotes: ["℘ 2Sam 23,30"] },
      { number: 14, text: "Und er hatte vierzig Söhne und dreißig Enkel, die auf siebzig Eseln ritten*. Und er richtete Israel acht Jahre.", footnotes: ["℘ Kap. 5,10"] },
      { number: 15, text: "Und Abdon, der Sohn Hillels, der Piratoniter, starb und wurde in Piraton begraben, im Land Ephraim, auf dem Amalekiterberg*.", footnotes: ["℘ Kap. 5,14"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "Und die Söhne Israel taten weiter, was böse war in den Augen des HERRN*. Da gab sie der HERR vierzig Jahre in die Hand der Philister*.", heading: "Simsons Geburt", footnotes: ["℘ Kap. 2,11", "℘ Kap. 10,7; 14,4; 1Sam 4,9"] },
      { number: 2, text: "Da war nun ein Mann aus Zora*, von einer Sippe der Daniter*, sein Name war Manoach. Seine Frau aber war unfruchtbar und gebar nicht*.", footnotes: ["℘ Jos 15,33; 1Chr 2,53", "℘ 1Mo 49,16", "℘ 1Mo 11,30"] },
      { number: 3, text: "Und der Engel des HERRN erschien der Frau* und sprach zu ihr: Sieh doch, du bist unfruchtbar und gebierst nicht; aber du wirst schwanger werden und einen Sohn gebären*.", footnotes: ["℘ Kap. 6,12; Lk 1,11.28", "℘ 1Mo 18,10; Lk 1,13.31"] },
      { number: 4, text: "Und nun, hüte dich doch und trinke weder Wein noch Rauschtrank und iss ja nichts Unreines*!", footnotes: ["℘ 4Mo 6,2.3"] },
      { number: 5, text: "Denn siehe, du wirst schwanger werden und einen Sohn gebären. Ein Schermesser soll nicht auf sein Haupt kommen, denn ein Nasiräer* Gottes soll der Junge sein vom Mutterleib an*. Er aber wird anfangen, Israel aus der Hand der Philister zu retten.", footnotes: ["d. h. ein Abgesonderter o. Geweihter", "℘ Kap. 16,17; 1Sam 1,11; Gal 1,15"] },
      { number: 6, text: "Und die Frau kam und sprach zu ihrem Mann und sagte: Ein Mann Gottes* ist zu mir gekommen, und sein Aussehen war wie das Aussehen des Engels Gottes*, sehr furchtbar. Ich habe ihn aber nicht gefragt, woher er sei, und seinen Namen hat er mir nicht genannt.", footnotes: ["℘ 1Sam 2,27; 1Kö 17,18", "℘ Apg 6,15; 10,3"] },
      { number: 7, text: "Und er sagte zu mir: Siehe, du wirst schwanger werden und einen Sohn gebären. Und nun, trinke weder Wein noch Rauschtrank und iss nichts Unreines; denn ein Nasiräer* Gottes soll der Junge sein vom Mutterleib an bis zum Tag seines Todes*.", footnotes: ["d. h. ein Abgesonderter o. Geweihter", "℘ Am 2,11"] },
      { number: 8, text: "Da betete Manoach zu dem HERRN und sagte: Bitte, Herr, der Mann Gottes, den du gesandt hast, möge doch noch einmal zu uns kommen und uns lehren, was wir tun sollen mit dem Jungen, der geboren werden soll." },
      { number: 9, text: "Und Gott hörte auf die Stimme Manoachs*. Und der Engel Gottes kam noch einmal zu der Frau, als sie gerade auf dem Feld saß und Manoach, ihr Mann, nicht bei ihr war.", footnotes: ["℘ 1Jo 5,14"] },
      { number: 10, text: "Da beeilte sich die Frau, lief, berichtete es ihrem Mann und sagte zu ihm: Siehe, der Mann ist mir erschienen, der an jenem Tag zu mir gekommen ist!" },
      { number: 11, text: "Da machte sich Manoach auf und folgte seiner Frau. Und er kam zu dem Mann und sagte zu ihm: Bist du der Mann, der zu der Frau geredet hat? Er sagte: Ich bin es." },
      { number: 12, text: "Und Manoach sagte: Nun, <wenn> dein Wort eintrifft, was soll die <Lebens>weise des Jungen und sein Tun sein*?", footnotes: ["℘ Ps 143,8.10"] },
      { number: 13, text: "Da sprach der Engel des HERRN zu Manoach: Vor allem, was ich der Frau gesagt habe, soll sie sich hüten." },
      { number: 14, text: "Von allem, was vom Weinstock kommt, soll sie nicht essen, und Wein und Rauschtrank soll sie nicht trinken, und sie soll nichts Unreines essen. Alles, was ich ihr geboten habe, soll sie beachten*.", footnotes: ["℘ 4Mo 6,2.3"] },
      { number: 15, text: "Und Manoach sagte zu dem Engel des HERRN: Wir hätten dich gern zurückgehalten und dir ein Ziegenböckchen zubereitet*.", footnotes: ["℘ Kap. 6,18"] },
      { number: 16, text: "Doch der Engel des HERRN sprach zu Manoach: Wenn du mich auch aufhieltest, ich würde nicht von deinem Brot essen. Willst du aber ein Brandopfer zubereiten, opfere es dem HERRN! Manoach hatte nämlich nicht erkannt, dass es der Engel des HERRN war." },
      { number: 17, text: "Da sagte Manoach zum Engel des HERRN: Wie* ist dein Name? Wenn dein Wort eintrifft, möchten wir dich ehren.", footnotes: ["w. Wer"] },
      { number: 18, text: "Doch der Engel des HERRN sprach zu ihm: Warum fragst du denn nach meinem Namen*? Er ist zu wunderbar*!", footnotes: ["℘ 1Mo 32,30", "℘ Neh 9,5; Jes 9,5"] },
      { number: 19, text: "Da nahm Manoach das Ziegenböckchen und das Speisopfer und opferte es dem HERRN auf dem Felsen. Er aber vollbrachte Wunderbares*, und Manoach und seine Frau sahen zu.", footnotes: ["LXX, Vulg., syr. Üs. lesen: opferte es auf dem Felsen dem HERRN, der Wunderbares vollbringt"] },
      { number: 20, text: "Es geschah nämlich, als die Flamme vom Altar zum Himmel emporstieg, da fuhr der Engel des HERRN in der Flamme des Altars hinauf*. Manoach aber und seine Frau sahen zu und fielen auf ihr Angesicht zur Erde*.", footnotes: ["℘ Kap. 6,19-21", "℘ 3Mo 9,24; 1Chr 21,16.26; Hes 1,28"] },
      { number: 21, text: "Der Engel des HERRN aber erschien Manoach und seiner Frau danach nicht mehr. Da <erst> erkannte Manoach, dass es der Engel des HERRN war." },
      { number: 22, text: "Und Manoach sagte zu seiner Frau: Ganz sicher müssen wir <jetzt> sterben, denn wir haben Gott gesehen*!", footnotes: ["℘ Kap. 6,22.23; 2Mo 3,6; 24,10"] },
      { number: 23, text: "Aber seine Frau sagte zu ihm: Wenn es dem HERRN gefallen hätte, uns zu töten, so hätte er aus unserer Hand nicht Brandopfer und Speisopfer angenommen*, und er hätte uns nicht dies alles sehen lassen und uns jetzt nicht so etwas hören lassen.", footnotes: ["℘ Ps 20,4"] },
      { number: 24, text: "Und die Frau gebar einen Sohn und gab ihm den Namen Simson*. Und der Junge wuchs heran, und der HERR segnete ihn*.", footnotes: ["℘ Hebr 11,32", "℘ 1Sam 2,21.26; Lk 1,80"] },
      { number: 25, text: "Und der Geist des HERRN fing an, ihn zu treiben* in Machaneh-Dan* zwischen Zora und Eschtaol*.", footnotes: ["℘ Kap. 3,10", "d. h. im Lager Dans\n℘ Kap. 18,12", "℘ Kap. 16,31; 18,2; Jos 19,41"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "Und Simson ging nach Timna* hinab. Und er sah in Timna eine Frau von den Töchtern der Philister*.", heading: "Simsons Kampf mit dem Löwen, seine Hochzeit und Überlistung durch die Philister", footnotes: ["℘ 1Mo 38,12; Jos 15,10", "℘ Kap. 16,1"] },
      { number: 2, text: "Und er ging <wieder> hinauf und berichtete es seinem Vater und seiner Mutter und sagte: Ich habe in Timna eine Frau von den Töchtern der Philister gesehen. Und nun nehmt sie mir <doch> zur Frau*!", footnotes: ["℘ 1Mo 34,4"] },
      { number: 3, text: "Da sagte sein Vater zu ihm und <auch> seine Mutter: Gibt es unter den Töchtern deiner Brüder und unter meinem ganzen Volk keine Frau*, dass du hingehst, eine Frau zu nehmen von den Philistern, den Unbeschnittenen*? Simson aber sagte zu seinem Vater: Diese nimm mir, denn sie ist in meinen Augen die Richtige!", footnotes: ["℘ 1Mo 24,3.4", "℘ Kap. 15,18; 1Mo 34,14; Jos 23,12"] },
      { number: 4, text: "Sein Vater und seine Mutter erkannten aber nicht, dass es von dem HERRN war*; denn er suchte einen Anlass bei den Philistern*. In jener Zeit herrschten nämlich die Philister über Israel*.", footnotes: ["℘ Jos 11,20; 1Kö 12,15", "℘ Kap. 15,3", "℘ Kap. 13,1; 15,11"] },
      { number: 5, text: "Und Simson ging mit seinem Vater und seiner Mutter nach Timna hinab. Als sie nun an die Weinberge von Timna kamen, siehe, da <sprang> ein Junglöwe brüllend ihm entgegen." },
      { number: 6, text: "Da kam der Geist des HERRN über ihn*. Und er zerriss ihn, wie man ein Böckchen zerreißt; und er hatte gar nichts in seiner Hand*. Aber seinem Vater und seiner Mutter erzählte er nicht, was er getan hatte*.", footnotes: ["℘ V. 19; Kap. 3,10", "℘ 1Sam 17,34.35; Hebr 11,33", "℘ 1Sam 10,16; 14,1"] },
      { number: 7, text: "Und er ging hinab und redete zu der Frau, und sie war die Richtige in den Augen Simsons." },
      { number: 8, text: "Und nach einiger Zeit kehrte er zurück, um sie zu nehmen. Und er bog <vom Weg> ab, um nach dem Kadaver des Löwen zu sehen, und siehe, da war ein Bienenschwarm in dem Körper des Löwen und Honig." },
      { number: 9, text: "Den löste er heraus<, nahm ihn> in seine Hände und ging weiter, wobei er im Gehen aß*. Und er ging zu seinem Vater und zu seiner Mutter und gab ihnen, und sie aßen. Aber er erzählte ihnen nicht*, dass er den Honig aus dem Körper des Löwen herausgelöst hatte.", footnotes: ["℘ Spr 24,13", "℘ 1Sam 10,16; 14,1"] },
      { number: 10, text: "Und sein Vater ging zu der Frau hinab, und Simson veranstaltete dort ein Festmahl*; denn so pflegten* es die jungen Männer zu tun.", footnotes: ["℘ 1Mo 29,22; Pred 10,19", "o. pflegen"] },
      { number: 11, text: "Und es geschah, als sie ihn sahen, da nahmen sie dreißig <Braut>begleiter; die waren bei ihm." },
      { number: 12, text: "Da sagte Simson zu ihnen: Ich will euch einmal ein Rätsel aufgeben*. Wenn ihr es mir in den sieben Tagen des Festmahls* richtig löst und es herausfindet, dann werde ich euch dreißig Hemden* und dreißig Festkleider geben*.", footnotes: ["℘ 1Kö 10,1; Hes 17,2", "℘ 1Mo 29,27", "das sind kostbare und ungewöhnliche Kleidungsstücke aus feinem Leinen", "℘ 1Mo 45,22; 2Kö 5,22"] },
      { number: 13, text: "Wenn ihr es mir aber nicht lösen könnt, dann müsst ihr mir dreißig Hemden* und dreißig Festkleider geben. Da sagten sie zu ihm: Gib dein Rätsel auf, wir wollen hören!", footnotes: ["das sind kostbare und ungewöhnliche Kleidungsstücke aus feinem Leinen"] },
      { number: 14, text: "Und er sagte zu ihnen: Aus dem Fresser kam Fraß, und aus dem Starken kam Süßes. Sie aber konnten das Rätsel nicht lösen drei Tage lang." },
      { number: 15, text: "Und es geschah am vierten* Tag, da sagten sie zu Simsons Frau: Betöre deinen Mann, dass er uns das Rätsel löst*, sonst verbrennen wir dich und das Haus deines Vaters mit Feuer*! Habt ihr uns eingeladen, um uns <aus unserm Besitz> zu vertreiben*? Ist es nicht so?", footnotes: ["so mit LXX und der syr. Üs.; Mas. T.: am siebten", "℘ Kap. 16,5", "℘ Kap. 12,1", "o. um uns in Besitz zu nehmen. — LXX: um uns arm zu machen"] },
      { number: 16, text: "Da weinte Simsons Frau bei ihm und sagte: Du hasst mich nur und liebst mich nicht. Den Söhnen meines Volkes hast du das Rätsel aufgegeben, aber mir hast du es nicht erzählt*. Er aber sagte zu ihr: Siehe, meinem Vater und meiner Mutter habe ich es nicht erzählt, da sollte ich es dir erzählen?", footnotes: ["℘ Kap. 16,15"] },
      { number: 17, text: "Doch sie weinte bei ihm die sieben Tage, an denen sie das Festmahl hielten. Und es geschah am siebten Tag, da erzählte er ihr <die Lösung des Rätsels>, weil sie ihn drängte*, und sie erzählte das Rätsel den Söhnen ihres Volkes*.", footnotes: ["℘ Kap. 16,16.17", "℘ Jer 9,3.4; Mi 7,5"] },
      { number: 18, text: "Da sagten die Männer der Stadt zu ihm am siebten Tag, bevor die Sonne unterging*: Was ist süßer als Honig, und was ist stärker als der Löwe? Er sagte zu ihnen: Wenn ihr nicht mit meinem Kalb gepflügt hättet, dann hättet ihr mein Rätsel nicht herausgefunden.", footnotes: ["o. bevor er nach <Timnat> Heres ging; andere lesen mit Änderung eines Buchstabens: bevor er ins Gemach ging; vgl. Kap. 15,1"] },
      { number: 19, text: "Und der Geist des HERRN kam über ihn*. Und er ging hinab nach Aschkelon* und erschlug dreißig Mann von ihnen und zog ihnen die Ausrüstung aus und gab die Festkleider denen, die das Rätsel gelöst hatten. Und sein Zorn entbrannte, so dass er ins Haus seines Vaters hinaufging.", footnotes: ["℘ V. 6", "℘ Kap. 1,18; 1Sam 6,4.17"] },
      { number: 20, text: "Simsons Frau aber wurde einem seiner <Braut>begleiter gegeben, der ihm als Brautführer gedient hatte*.", footnotes: ["℘ Kap. 15,2; 1Sam 18,19"] },
    ]},
    { number: 15, verses: [
      { number: 1, text: "Und es geschah nach einiger Zeit, in den Tagen der Weizenernte, da suchte Simson seine Frau mit einem Ziegenböckchen auf, und er sagte: Ich will zu meiner Frau in die Kammer hineingehen. Aber ihr Vater gestattete ihm nicht hineinzugehen.", heading: "Simsons Rache: Brand des Getreides" },
      { number: 2, text: "Und ihr Vater sagte: Ich habe fest angenommen, dass du sie nur noch hassen würdest, da habe ich sie deinem <Braut>begleiter gegeben*. Ist nicht ihre jüngere Schwester schöner als sie? Sie soll dir an ihrer Stelle gehören.", footnotes: ["℘ Kap. 14,20"] },
      { number: 3, text: "Da sagte Simson zu ihnen: Diesmal bin ich ohne Schuld an den Philistern, wenn ich ihnen Übles tue*.", footnotes: ["℘ Kap. 14,4"] },
      { number: 4, text: "Und Simson ging hin und fing dreihundert Füchse. Und er nahm Fackeln und kehrte Schwanz zu Schwanz und befestigte eine Fackel zwischen je zwei Schwänzen in der Mitte." },
      { number: 5, text: "Dann zündete er die Fackeln mit Feuer an, ließ <die Füchse> los in das stehende Getreide der Philister* und steckte <alles> in Brand vom Garbenhaufen bis zum stehenden Getreide, ja, bis zum Weinberg <und> Olivenbaum.", footnotes: ["℘ 2Sam 14,30"] },
      { number: 6, text: "Da sagten die Philister: Wer hat das getan? Und man sagte: Simson, der Schwiegersohn des Timniters, weil er ihm seine Frau weggenommen und sie seinem <Braut>begleiter gegeben hat. Da zogen die Philister hinauf und verbrannten sie und ihren Vater mit Feuer*.", footnotes: ["℘ Kap. 12,1"] },
      { number: 7, text: "Und Simson sagte zu ihnen: Wenn ihr es so macht — erst wenn ich mich an euch gerächt habe, <erst> danach will ich aufhören!" },
      { number: 8, text: "Und er schlug sie gründlich zusammen* — ein gewaltiger Schlag. Und er ging hinab und blieb in der Felsspalte von Etam*.", footnotes: ["w. er schlug sie — Unterschenkel über Oberschenkel", "℘ 2Chr 11,6"] },
      { number: 9, text: "Und die Philister zogen herauf und lagerten in Juda und breiteten sich in Lehi aus.", heading: "Simson erschlägt tausend Philister" },
      { number: 10, text: "Da sagten die Männer von Juda: Warum seid ihr gegen uns heraufgezogen? Sie sagten: Um Simson zu binden, sind wir heraufgezogen, um ihm zu tun, wie er uns getan hat*.", footnotes: ["℘ V. 8"] },
      { number: 11, text: "Da zogen dreitausend Mann von Juda zur Felsspalte von Etam hinab und sagten zu Simson: Weißt du nicht, dass die Philister über uns herrschen*? Was hast du uns da angetan? Er sagte zu ihnen: Wie sie mir getan, so habe ich ihnen getan.", footnotes: ["℘ Kap. 14,4; Ps 106,41; Joh 8,33"] },
      { number: 12, text: "Da sagten sie zu ihm: Um dich zu binden, sind wir herabgekommen, um dich in die Hand der Philister auszuliefern. Simson sagte zu ihnen: Schwört mir, dass nicht ihr selber über mich herfallen werdet!" },
      { number: 13, text: "Und sie sagten zu ihm: Nein, sondern wir wollen dich nur binden und dich in ihre Hand ausliefern, aber töten wollen wir dich nicht. So banden sie ihn mit zwei neuen Stricken und führten ihn vom Felsen herauf." },
      { number: 14, text: "Als er nach Lehi kam, da jauchzten ihm die Philister entgegen*. Aber der Geist des HERRN kam über ihn*, da wurden die Stricke, die an seinen Armen waren, wie Flachsfäden, die vom Feuer versengt sind, und seine Fesseln schmolzen von seinen Händen weg*.", footnotes: ["℘ Kap. 16,24", "℘ Kap. 3,10; 1Sam 10,6.10", "℘ Kap. 16,9.12"] },
      { number: 15, text: "Und er fand einen <noch> frischen Unterkiefer eines Esels, und er streckte seine Hand aus, nahm ihn und erschlug damit tausend Mann*.", footnotes: ["℘ Kap. 3,31; 3Mo 26,8; 2Sam 23,8"] },
      { number: 16, text: "Und Simson sprach: Mit dem Unterkiefer des Esels <schlug ich> einen Haufen, zwei Haufen*! Mit dem Unterkiefer des Esels erschlug ich tausend Mann!", footnotes: ["ein Wortspiel, da im Hebr. »Esel« und »Haufen« gleiche Wörter sind"] },
      { number: 17, text: "Und es geschah, als er ausgeredet hatte, warf er den Unterkiefer aus seiner Hand. Und man* nannte jenen Ort Ramat-Lehi*.", footnotes: ["o. er", "d. h. Unterkiefer-Höhe"] },
      { number: 18, text: "Und er hatte großen Durst. Da rief er zu dem HERRN und sagte: Du hast durch die Hand* deines Knechtes diese große Rettung gegeben, nun aber muss ich vor Durst sterben und in die Hand der Unbeschnittenen fallen*!", footnotes: ["o. in die Hand", "℘ Kap. 14,3"] },
      { number: 19, text: "Da spaltete Gott die Höhlung, die bei Lehi ist*, so dass Wasser aus ihr hervorkam*. Und er trank, und sein Geist kehrte zurück, und er lebte <wieder> auf*. Daher gab man ihr den Namen: Quelle des Rufenden*; die ist bei Lehi bis auf diesen Tag.", footnotes: ["o. die Vertiefung <der Zähne>, die in dem Unterkiefer war", "℘ 4Mo 20,11; Jes 41,17.18", "℘ 1Sam 30,12; Ps 50,15; 110,7", "hebr. en hakore"] },
      { number: 20, text: "Und er richtete Israel in den Tagen der Philister zwanzig Jahre*.", footnotes: ["℘ Kap. 16,31; 1Mo 49,16; 1Sam 4,18"] },
    ]},
    { number: 16, verses: [
      { number: 1, text: "Und Simson ging nach Gaza*. Dort sah er eine Hure* und ging zu ihr hinein.", heading: "Simson zu Gaza", footnotes: ["℘ Kap. 1,18", "℘ Kap. 14,1.2; 1Kor 6,18"] },
      { number: 2, text: "<Das berichtete man> den Gazitern und sagte: Simson ist hierhergekommen. Da umstellten sie ihn und lauerten ihm die ganze Nacht im Stadttor auf. Und sie verhielten sich die ganze Nacht still und sagten: Bis der Morgen hell wird, dann wollen wir ihn erschlagen*.", footnotes: ["℘ 1Sam 19,11; Apg 9,23.24"] },
      { number: 3, text: "Und Simson lag bis Mitternacht. Um Mitternacht aber stand er auf und packte die Flügel des Stadttores und die beiden Pfosten und riss sie samt dem Riegel heraus und legte sie auf seine Schultern. Und er trug sie auf den Gipfel des Berges, der nach Hebron zu <liegt>." },
      { number: 4, text: "Und es geschah danach, da gewann er eine Frau im Tal Sorek lieb, ihr Name war Delila.", heading: "Simson bei Delila — sein Fall" },
      { number: 5, text: "Da gingen die Fürsten der Philister zu ihr hinauf und sagten zu ihr: Betöre ihn und sieh, wodurch seine Kraft so groß ist und wodurch wir ihn überwältigen können, dass wir ihn binden, um ihn zu bezwingen*! Wir wollen dir jeder 1 100 <Schekel> Silber geben*.", footnotes: ["℘ Kap. 14,15", "℘ Mt 26,15"] },
      { number: 6, text: "Da sagte Delila zu Simson: Vertrau mir doch an, wodurch deine Kraft so groß ist und womit man dich binden muss, um dich zu bezwingen!" },
      { number: 7, text: "Und Simson sagte zu ihr: Wenn man mich mit sieben frischen Sehnen* bindet, die nicht ausgetrocknet sind, dann werde ich schwach werden und wie ein anderer Mensch sein.", footnotes: ["d. h. vom Schlachten noch feuchte Sehnen, die sich beim Trocknen zusammenziehen"] },
      { number: 8, text: "Da brachten die Fürsten der Philister sieben frische Sehnen*, die nicht ausgetrocknet waren, zu ihr hinauf. Und sie band ihn damit,", footnotes: ["d. h. vom Schlachten noch feuchte Sehnen, die sich beim Trocknen zusammenziehen"] },
      { number: 9, text: "während die Lauernden bei ihr in der Kammer saßen*. Und sie sagte zu ihm: Philister über dir, Simson! Da zerriss er die Sehnen, wie ein Faden aus Werg zerreißt, wenn es Feuer riecht*. So wurde seine Kraft nicht erkannt.", footnotes: ["w. während der Lauernde . . . saß", "℘ Kap. 15,14"] },
      { number: 10, text: "Da sagte Delila zu Simson: Siehe, du hast mich getäuscht und Lügen zu mir geredet. Vertrau mir doch jetzt an, womit man dich binden muss!" },
      { number: 11, text: "Er sagte zu ihr: Wenn man mich ganz fest mit neuen Stricken, mit denen keine Arbeit getan worden ist, bindet, dann werde ich schwach werden und wie ein anderer Mensch sein." },
      { number: 12, text: "Da nahm Delila neue Stricke und band ihn damit. Dann sagte sie zu ihm, während <wieder> die Lauernden in der Kammer saßen*: Philister über dir, Simson! Da riss er sie von seinen Armen wie einen Faden*.", footnotes: ["w. während der Lauernde . . . saß", "℘ Kap. 15,14"] },
      { number: 13, text: "Da sagte Delila zu Simson: Bisher hast du mich getäuscht und Lügen zu mir geredet. Vertrau mir <doch endlich> an, womit man dich binden muss! Er sagte zu ihr: Wenn du die sieben Haarflechten meines Kopfes mit den Kettfäden <am Webstuhl> verwebtest." },
      { number: 14, text: "Und sie machte* sie mit dem Pflock fest und sagte zu ihm: Philister über dir, Simson! Da wachte er aus seinem Schlaf auf und riss den Weberpflock und die Kettfäden heraus.", footnotes: ["w. schlug"] },
      { number: 15, text: "Da sagte sie zu ihm: Wie kannst du sagen: Ich habe dich lieb! — wo doch dein Herz nicht mit mir ist? Dreimal hast du mich jetzt getäuscht und mir nicht anvertraut, wodurch deine Kraft so groß ist*.", footnotes: ["℘ Kap. 14,16.17"] },
      { number: 16, text: "Und es geschah, als sie ihn alle Tage mit ihren Worten bedrängte und ihn plagte*, da wurde seine Seele es zum Sterben leid,", footnotes: ["℘ Kap. 14,16.17"] },
      { number: 17, text: "und er vertraute ihr sein ganzes Herz an* und sagte zu ihr: Nie ist ein Schermesser auf mein Haupt gekommen, denn ein Nasiräer* Gottes bin ich von Mutterleib an*. Wenn ich geschoren werde, dann weicht meine Kraft von mir, und ich werde schwach wie jeder <andere> Mensch sein.", footnotes: ["℘ Spr 13,3", "d. h. ein Abgesonderter o. Geweihter", "℘ Kap. 13,5; 4Mo 6,5; 2Kor 3,5"] },
      { number: 18, text: "Und als Delila sah, dass er ihr sein ganzes Herz anvertraut hatte, sandte sie hin und rief die Fürsten der Philister und <ließ ihnen> sagen: Diesmal kommt herauf, denn er hat mir sein ganzes Herz anvertraut! Da kamen die Fürsten der Philister zu ihr herauf, und in ihrer Hand brachten sie das Geld mit." },
      { number: 19, text: "Und sie ließ ihn auf ihren Knien einschlafen*. Dann rief sie den Mann und ließ die sieben Haarflechten seines Hauptes abscheren. So begann sie, ihn zu bezwingen*, und seine Kraft wich von ihm.", footnotes: ["℘ Lk 22,46", "LXX: So begann er, schwach zu werden\n℘ Pred 7,26"] },
      { number: 20, text: "Und sie sagte: Philister über dir, Simson! Da wachte er auf von seinem Schlaf und sagte <sich>: Ich werde davonkommen, wie es Mal für Mal <gelang>, und werde mich freischütteln. Er wusste aber nicht, dass der HERR von ihm gewichen war*.", footnotes: ["℘ 4Mo 14,43; 1Sam 16,14; 18,12"] },
      { number: 21, text: "Und die Philister packten ihn und stachen ihm die Augen aus. Und sie führten ihn nach Gaza hinab und banden ihn mit ehernen Fesseln*, und er musste im Gefängnis die Mühle drehen.", footnotes: ["w. bronzenen Doppelfesseln\n℘ 2Kö 25,7"] },
      { number: 22, text: "Aber das Haar seines Hauptes begann <wieder> zu wachsen, nachdem es geschoren worden war." },
      { number: 23, text: "Und die Fürsten der Philister versammelten sich zu einem Freudenfest, um ihrem Gott Dagon* ein großes Schlachtopfer darzubringen*. Denn sie sagten: Unser Gott hat Simson, unseren Feind, in unsere Hand gegeben.", heading: "Simsons Rache und Tod", footnotes: ["℘ 1Sam 5,2", "w. zu schlachten"] },
      { number: 24, text: "Und als das Volk ihn sah, lobten sie ihren Gott. Denn sie sagten: Unser Gott hat unseren Feind in unsere Hand gegeben, den, der unser Land verheerte, und den, der unsere Erschlagenen zahlreich machte*.", footnotes: ["℘ Kap. 15,14; Offb 11,10"] },
      { number: 25, text: "Und es geschah, als ihr Herz fröhlich war, sagten sie: Ruft Simson herbei, er soll für uns Späße machen*! Und sie riefen Simson aus dem Gefängnis, und er musste vor ihnen Späße machen*. Und sie stellten ihn zwischen die Säulen.", footnotes: ["o. für uns tanzen", "o. tanzen"] },
      { number: 26, text: "Und Simson sagte zu dem Jungen, der ihn an der Hand hielt: Lass mich, dass ich die Säulen betaste, auf denen das Haus ruht. Ich will mich an sie lehnen." },
      { number: 27, text: "Das Haus war aber voll von Männern und Frauen, und alle Fürsten der Philister waren <ebenfalls> dort. Und auf dem Dach waren an die dreitausend Männer und Frauen, die zusahen, wie* Simson Späße machen* musste.", footnotes: ["o. während", "o. tanzen"] },
      { number: 28, text: "Da rief Simson zu dem HERRN und sagte: Herr, HERR! Denke doch an mich* und stärke mich doch nur diesmal <noch>, Gott, damit ich Rache nehmen kann an den Philistern — eine Rache <nur> für meine beiden Augen!", footnotes: ["℘ Ps 10,12; Jer 15,15"] },
      { number: 29, text: "Dann umfasste Simson die beiden Mittelsäulen, auf denen das Haus ruhte, stemmte sich gegen sie — <gegen> die eine mit seiner Rechten und <gegen> die andere mit seiner Linken." },
      { number: 30, text: "Und Simson sagte: Meine Seele sterbe mit den Philistern! Und er beugte sich mit <aller> Kraft. Da fiel das Haus auf die Fürsten und auf alles Volk, das darin war. So waren die Toten, die er mit seinem Tod tötete, zahlreicher als die, die er in seinem Leben getötet hatte." },
      { number: 31, text: "Und seine Brüder und das ganze Haus seines Vaters kamen herab und hoben ihn auf. Und sie brachten <ihn> hinauf und begruben ihn zwischen Zora und Eschtaol* im Grab seines Vaters Manoach. Er hatte aber Israel zwanzig Jahre gerichtet*.", footnotes: ["℘ Kap. 13,25", "℘ Kap. 15,20"] },
    ]},
    { number: 17, verses: [
      { number: 1, text: "Und es war ein Mann vom Gebirge Ephraim*, sein Name war Micha*.", heading: "Michas Bilderdienst", footnotes: ["℘ Kap. 3,27; Jos 17,15; 21,21; 24,30", "℘ Kap. 18,2"] },
      { number: 2, text: "Der sagte zu seiner Mutter: Die 1 100 Silberstücke, die dir genommen worden sind und derentwegen du einen Fluch ausgestoßen und ihn auch vor meinen Ohren ausgesprochen hast — siehe, das Silber ist bei mir. Ich selbst habe es genommen*. Da sagte seine Mutter: Sei gesegnet dem HERRN*, mein Sohn*!", footnotes: ["℘ Ps 10,3", "o. von dem HERRN", "℘ 1Sam 15,13"] },
      { number: 3, text: "Und er gab die 1 100 Silberstücke seiner Mutter zurück. Und seine Mutter sagte: Hiermit erkläre ich nun das Silber als heilig für den HERRN*! Für meinen Sohn <gehe es> aus meiner Hand, damit man ein Schnitzbild und ein Gussbild <davon> mache*! Und jetzt gebe ich es dir zurück.", footnotes: ["o. Geheiligt hatte ich das Silber für den HERRN", "℘ 2Mo 20,4.23"] },
      { number: 4, text: "Aber er gab das Silber seiner Mutter zurück. Und seine Mutter nahm zweihundert Silberstücke und gab sie dem Goldschmied, und der machte davon ein Schnitzbild und ein Gussbild*; das war nun in Michas Haus*.", footnotes: ["℘ Kap. 18,17; Jes 46,6; Hab 2,18.19", "℘ 5Mo 27,15"] },
      { number: 5, text: "So hatte der Mann Micha ein Gotteshaus. Und er machte ein Efod* und Terafim* und weihte einen von seinen Söhnen*; der wurde sein Priester*.", footnotes: ["℘ Kap. 8,27", "℘ 1Mo 31,19; 1Sam 19,13; Hes 21,26; Hos 3,4", "w. füllte einem von seinen Söhnen die Hand", "℘ 2Mo 29,9; 1Kö 12,32"] },
      { number: 6, text: "In jenen Tagen war kein König in Israel*. Jeder tat, was recht war in seinen Augen*.", footnotes: ["℘ Kap. 18,1; 19,1", "℘ Kap. 21,25; 5Mo 12,8; Spr 16,2"] },
      { number: 7, text: "Nun war da ein junger Mann aus Bethlehem <in> Juda*, aus einer Sippe <in> Juda; der war ein Levit*, und er wohnte als Fremder dort.", footnotes: ["℘ Kap. 12,8; Rt 1,1.2; Mi 5,1", "Man betrachtete die Leviten als Angehörige des Stammes, in dessen Gebiet sie wohnten.\n℘ Kap. 12,5"] },
      { number: 8, text: "Und der Mann zog aus der Stadt, aus Bethlehem <in> Juda fort, um als Fremder zu wohnen, wo er es <gerade> träfe. Und indem er seinen Weg zog, kam er ins Gebirge Ephraim zum Haus Michas." },
      { number: 9, text: "Und Micha sagte zu ihm: Woher kommst du? Er sagte zu ihm: Ich bin ein Levit aus Bethlehem <in> Juda. Ich bin auf der Wanderschaft, um als Fremder zu wohnen, wo ich es <gerade> treffen werde." },
      { number: 10, text: "Da sagte Micha zu ihm: Bleibe bei mir und werde mir zum Vater* und zum Priester! Und ich will dir jährlich zehn Silberstücke geben und Ausrüstung an Kleidern und deinen Lebensunterhalt*. Da ging der Levit <zu ihm hinein>.", footnotes: ["℘ Kap. 18,19; 1Mo 45,8; 2Kö 2,12", "℘ 1Sam 2,36"] },
      { number: 11, text: "Und der Levit entschloss sich, bei dem Mann zu bleiben. Und für den wurde der junge Mann wie einer seiner Söhne." },
      { number: 12, text: "Und Micha weihte den Leviten*. Und der junge Mann wurde sein Priester* und war <für immer> im Haus Michas.", footnotes: ["w. Und Micha füllte die Hand des Leviten", "℘ Kap. 18,4"] },
      { number: 13, text: "Und Micha sagte: Jetzt weiß ich, dass der HERR mir Gutes tun wird, denn ich habe den Leviten zum Priester*.", footnotes: ["℘ Kap. 18,24"] },
    ]},
    { number: 18, verses: [
      { number: 1, text: "In jenen Tagen gab es keinen König in Israel*. Und in jenen Tagen suchte sich der Stamm der Daniter ein Erbteil zum Wohnen; denn bis zu jenem Tag war ihm mitten unter den Stämmen Israels nichts als Erbteil zugefallen*.", heading: "Ein neues Stammesgebiet für Dan", footnotes: ["℘ Kap. 17,6", "℘ Kap. 1,34"] },
      { number: 2, text: "Und die Söhne Dan sandten fünf Männer aus ihrer Sippe, aus ihrer Gesamtheit, tapfere Männer aus Zora und aus Eschtaol*, um das Land auszukundschaften und es zu erforschen*. Und sie sagten zu ihnen: Geht hin, erforscht das Land! Und sie kamen in das Gebirge Ephraim zum Haus Michas* und übernachteten dort.", footnotes: ["℘ Kap. 13,25", "℘ Jos 2,2", "℘ Kap. 17,1"] },
      { number: 3, text: "Als sie beim Haus Michas waren, erkannten sie die Mundart* des jungen Mannes, des Leviten. Und sie bogen dahin ab und sagten zu ihm: Wer hat dich hierhergebracht? Und was tust du hier? Und was hast du hier?", footnotes: ["w. Stimme"] },
      { number: 4, text: "Und er sagte zu ihnen: So und so hat Micha mir getan. Und er hat mich in Lohn genommen, und ich bin sein Priester geworden*.", footnotes: ["℘ Kap. 17,10-12"] },
      { number: 5, text: "Da sagten sie zu ihm: Befrage doch Gott, damit wir erkennen, ob unser Weg, auf dem wir gehen, zum Ziel führt*!", footnotes: ["℘ 1Sam 9,9; Hos 4,12"] },
      { number: 6, text: "Da sagte der Priester zu ihnen: Geht in Frieden*! Vor dem HERRN <liegt> euer Weg, auf dem ihr geht.", footnotes: ["℘ 2Mo 4,18"] },
      { number: 7, text: "Und die fünf Männer gingen hin und kamen nach Lajisch*. Und sie sahen das Volk, das darin war, in Sicherheit wohnen, nach Art der Sidonier, ruhig und arglos*. Und es gab keinen, der einem irgendetwas zuleide tat im Land, <oder> der <fremdes> Vermögen in Besitz genommen hätte*. Und sie waren <weit> entfernt von den Sidoniern und hatten mit den Aramäern* nichts zu tun*. —", footnotes: ["℘ V. 29", "o. sorglos; o. sicher", "o. im Land <keinen> Eroberer, <keine> Unterdrückung", "so mit LXX und der syr. Üs.; Mas. T.: mit <irgend>einem Menschen", "℘ 1Chr 4,40"] },
      { number: 8, text: "Und sie kamen <zurück> zu ihren Brüdern nach Zora und Eschtaol. Und ihre Brüder sagten zu ihnen: Was <bringt> ihr?" },
      { number: 9, text: "Sie sagten: Macht euch auf und lasst uns gegen sie hinaufziehen! Denn wir haben uns das Land angesehen, und siehe, es ist sehr gut*. Und ihr bleibt <noch> untätig? Seid nicht träge zu gehen, um hinzukommen, das Land in Besitz zu nehmen*!", footnotes: ["℘ 4Mo 14,7-9", "℘ Jos 18,3; 1Kö 22,3"] },
      { number: 10, text: "Wenn ihr hinkommt, werdet ihr zu einem arglosen* Volk kommen, und das Land ist geräumig nach <allen> Seiten hin. Ja, Gott hat es in eure Hand gegeben*, einen Ort, wo es keinen Mangel gibt an irgendetwas, was auf Erden ist*.", footnotes: ["o. sorglosen; o. sicheren", "℘ Jos 2,23.24", "℘ 5Mo 8,7-9"] },
      { number: 11, text: "Da brachen sechshundert Mann von dort auf, von der Sippe der Daniter, aus Zora und aus Eschtaol, umgürtet mit Waffen.", heading: "Der Stamm Dan beraubt das Heiligtum Michas" },
      { number: 12, text: "Und sie zogen hinauf und lagerten zu Kirjat-Jearim in Juda*. Daher hat man diesen Ort Machaneh-Dan* genannt bis auf diesen Tag; siehe, er <liegt> hinter Kirjat-Jearim.", footnotes: ["℘ Jos 15,9.60; 1Sam 6,21", "d. h. Heerlager Dans\n℘ Kap. 13,25"] },
      { number: 13, text: "Und von dort zogen sie weiter ins Gebirge Ephraim und kamen zum Haus Michas." },
      { number: 14, text: "Da begannen die fünf Männer, die gegangen waren, das Land Lajisch auszukundschaften, und sagten zu ihren Brüdern: Wisst ihr, dass in diesen Häusern Efod und Terafim und ein Schnitzbild und ein Gussbild sind? Und nun erkennt, was ihr zu tun habt!" },
      { number: 15, text: "Da bogen sie dahin ab und traten in das Haus des jungen Mannes, des Leviten, ein, in das Haus Michas, und fragten ihn nach seinem Wohlergehen*.", footnotes: ["℘ 1Sam 17,22"] },
      { number: 16, text: "Die sechshundert mit ihren Waffen umgürteten Männer aber, die von den Söhnen Dan waren, blieben am Eingang des Tores stehen." },
      { number: 17, text: "<Nur> die fünf Männer, die gegangen waren, das Land auszukundschaften, stiegen hinauf, gingen dort hinein <und> nahmen das Schnitzbild und das Efod und die Terafim und das Gussbild*. Und der Priester und die sechshundert Mann, die mit Waffen umgürtet waren, standen am Eingang des Tores.", footnotes: ["℘ Kap. 17,4"] },
      { number: 18, text: "Als jene nun in Michas Haus gingen und das Schnitzbild, das Efod und die Terafim und das Gussbild wegnahmen, da sagte der Priester zu ihnen: Was tut ihr da?" },
      { number: 19, text: "Sie sagten zu ihm: Schweig! Lege deine Hand auf deinen Mund und geh mit uns und sei für uns Vater und Priester*! Ist es besser für dich, Priester zu sein für das Haus eines einzelnen Mannes oder Priester zu sein für einen Stamm und für eine Sippe in Israel?", footnotes: ["℘ Kap. 17,10"] },
      { number: 20, text: "Da wurde das Herz des Priesters froh*, und er nahm das Efod und die Terafim und das Schnitzbild und ging mitten unter das Volk.", footnotes: ["℘ Jes 56,11; Röm 16,18"] },
      { number: 21, text: "Und sie wandten sich und gingen <weiter> und stellten die Kinder und das Vieh und die wertvollen Dinge an ihre Spitze." },
      { number: 22, text: "Sie hatten sich <schon ein Stück weit> von Michas Haus entfernt, da wurden die Männer zusammengerufen, die in den Häusern <wohnten>, die beim Haus Michas <standen>, und sie holten die Söhne Dan ein." },
      { number: 23, text: "Und sie riefen die Söhne Dan an; und diese wandten ihr Gesicht um und sagten zu Micha: Was ist dir, dass du dich hast rufen lassen?" },
      { number: 24, text: "Er sagte: Meine Götter, die ich gemacht hatte, habt ihr <mir> weggenommen und den Priester dazu, und seid weggezogen! Was <bleibt> mir da noch*? Und wie könnt ihr denn zu mir sagen: Was ist dir?", footnotes: ["℘ Kap. 17,13; 1Mo 31,30.34; 2Chr 25,15"] },
      { number: 25, text: "Aber die Söhne Dan sagten zu ihm: Lass deine Stimme bei uns nicht <mehr> hören, damit nicht Männer mit erbittertem Mut* über euch herfallen und du dein Leben verwirkst* und das Leben deines Hauses!", footnotes: ["o. mit grimmigem Gemüt", "w. aufsammelst"] },
      { number: 26, text: "Und die Söhne Dan zogen ihres Weges. Und als Micha sah, dass sie stärker waren als er, wandte er sich und kehrte in sein Haus zurück." },
      { number: 27, text: "Jene aber nahmen mit, was Micha gemacht hatte, dazu den Priester, den er besaß. Und sie kamen über Lajisch, über ein ruhiges und argloses* Volk, und schlugen es mit der Schärfe des Schwertes; und die Stadt verbrannten sie mit Feuer*.", footnotes: ["o. sorgloses; o. sicheres", "℘ 5Mo 33,22"] },
      { number: 28, text: "Und kein Retter war da; denn die Stadt* war <weit> entfernt von Sidon, und sie hatten mit den Aramäern* nichts zu tun. Sie <lag> in der Ebene, die zu Bet-Rehob* gehört. Und sie bauten die Stadt <wieder> auf und wohnten in ihr.", footnotes: ["w. sie", "so mit LXX und der syr. Üs.; Mas. T.: mit <irgend>einem Menschen", "℘ 4Mo 13,21; Jos 19,28; 2Sam 10,6.8"] },
      { number: 29, text: "Und sie gaben der Stadt den Namen Dan nach dem Namen ihres Vaters Dan, der dem Israel geboren worden war; früher dagegen war Lajisch der Name der Stadt*. —", footnotes: ["℘ V. 7; 1Mo 14,14; 5Mo 34,1; Jos 19,47; 1Kö 12,29; 15,20"] },
      { number: 30, text: "Und die Söhne Dan richteten sich das Schnitzbild auf*. Und Jonatan, der Sohn Gerschoms, des Sohnes des Mose*, er und seine Söhne waren Priester für den Stamm der Daniter bis zum Tag der Wegführung <der Bevölkerung> des Landes*.", footnotes: ["℘ 3Mo 26,1", "viele hebr. Handschr.: des Manasse", "℘ 2Kö 15,29; 17,22.23"] },
      { number: 31, text: "Und sie stellten sich das Schnitzbild Michas auf, das er gemacht hatte, all die Tage, in denen das Haus Gottes in Silo war*.", footnotes: ["℘ Jos 18,1"] },
    ]},
    { number: 19, verses: [
      { number: 1, text: "Und es geschah in jenen Tagen — einen König gab es <damals> nicht in Israel* —, es geschah also, dass ein levitischer Mann am äußersten Ende des Gebirges Ephraim* als Fremder wohnte, der nahm sich eine Nebenfrau aus Bethlehem <in> Juda*.", heading: "Die Schandtat der Männer von Gibea", footnotes: ["℘ Kap. 17,6", "℘ Kap. 3,27", "℘ Kap. 12,8"] },
      { number: 2, text: "Und seine Nebenfrau war wütend auf ihn* und lief weg von ihm ins Haus ihres Vaters nach Bethlehem <in> Juda und war dort eine Zeit lang, <nämlich> vier Monate.", footnotes: ["o. hurte neben ihm"] },
      { number: 3, text: "Da machte sich ihr Mann auf und ging ihr nach, um zu ihrem Herzen zu reden* <und> sie zurückzubringen. Und er hatte seinen Knecht und ein Paar Esel bei sich. Sie aber führte ihn in das Haus ihres Vaters. Und als der Vater der jungen Frau* ihn sah, kam er ihm freudig entgegen.", footnotes: ["℘ 1Mo 34,3", "w. des Mädchens. — Auch eine verheiratete junge Frau hieß für die Eltern »Mädchen«."] },
      { number: 4, text: "Und sein Schwiegervater, der Vater der jungen Frau, hielt ihn zurück, und er blieb drei Tage bei ihm. Und sie aßen und tranken und übernachteten dort." },
      { number: 5, text: "Und es geschah am vierten Tag, da machten sie sich früh am Morgen auf, und er erhob sich, um fortzugehen. Da sagte der Vater der jungen Frau* zu seinem Schwiegersohn: Stärke dein Herz mit einem Bissen Brot*, und danach könnt ihr gehen!", footnotes: ["w. des Mädchens. — Auch eine verheiratete junge Frau hieß für die Eltern »Mädchen«.", "℘ 1Mo 18,5; Ps 104,15"] },
      { number: 6, text: "So blieben sie denn, aßen beide miteinander und tranken. Und der Vater der jungen Frau* sagte zu dem Mann: Tu <mir> doch den Gefallen und bleib über Nacht und lass dein Herz fröhlich sein*!", footnotes: ["w. des Mädchens. — Auch eine verheiratete junge Frau hieß für die Eltern »Mädchen«.", "℘ Rt 3,7"] },
      { number: 7, text: "Doch der Mann erhob sich, um fortzugehen. Da drang sein Schwiegervater in ihn, so dass er wieder dort übernachtete." },
      { number: 8, text: "Und am fünften Tag machte er sich früh am Morgen auf, um fortzugehen. Da sagte der Vater der jungen Frau*: Stärke doch dein Herz und verweilt, bis der Tag sich neigt! So aßen sie beide <miteinander>.", footnotes: ["w. des Mädchens. — Auch eine verheiratete junge Frau hieß für die Eltern »Mädchen«."] },
      { number: 9, text: "Dann erhob sich der Mann, um fortzugehen, er und seine Nebenfrau und sein Knecht. Aber sein Schwiegervater, der Vater der jungen Frau*, sagte zu ihm: Sieh doch, der Tag nimmt ab, es will Abend werden. Übernachtet doch! Siehe, der Tag sinkt, übernachte hier und lass dein Herz fröhlich sein! Morgen früh könnt ihr euch dann auf euren Weg machen, und du magst zu deinem Zelt gehen.", footnotes: ["w. des Mädchens. — Auch eine verheiratete junge Frau hieß für die Eltern »Mädchen«."] },
      { number: 10, text: "Aber der Mann wollte nicht übernachten, sondern erhob sich und zog fort. Und er kam bis gegenüber von Jebus, das ist Jerusalem*, und bei ihm war das Paar gesattelter Esel, und seine Nebenfrau war bei ihm.", footnotes: ["℘ Jos 15,8.63; 18,28"] },
      { number: 11, text: "Sie waren bei Jebus, und der Tag war sehr gesunken, da sagte der Knecht zu seinem Herrn: Komm doch und lass uns in diese Stadt der Jebusiter* einkehren und darin übernachten!", footnotes: ["℘ Kap. 1,21"] },
      { number: 12, text: "Sein Herr aber sagte zu ihm: Wir wollen nicht in einer Stadt von Fremden einkehren, die nicht von den Söhnen Israel sind, sondern wir wollen nach Gibea* hinübergehen.", footnotes: ["℘ Jos 18,25.28"] },
      { number: 13, text: "Und er sagte zu seinem Knecht: Komm, wir wollen uns einem der Orte nähern und in Gibea* oder in Rama* übernachten!", footnotes: ["℘ Jos 18,25.28", "℘ Jes 10,29; Hos 5,8"] },
      { number: 14, text: "So zogen sie vorüber und gingen weiter, aber die Sonne ging ihnen unter nahe bei Gibea, das zu Benjamin gehört." },
      { number: 15, text: "Und sie wandten sich dorthin, dass sie hineinkämen, um in Gibea zu übernachten*. Und er kam hinein und ließ sich auf dem Platz der Stadt nieder, da es niemanden gab, der sie zum Übernachten ins Haus aufgenommen hätte.", footnotes: ["℘ Kap. 20,4"] },
      { number: 16, text: "Und siehe, ein alter Mann kam von seiner Arbeit, <spät> abends vom Feld*. Der Mann war vom Gebirge Ephraim und wohnte als Fremder in Gibea. Die Männer des Ortes aber waren Benjaminiter.", footnotes: ["℘ Ps 104,23"] },
      { number: 17, text: "Als der nun seine Augen erhob, sah er den Wandersmann auf dem Platz der Stadt, und der alte Mann sagte: Wohin gehst du? Und woher kommst du*?", footnotes: ["℘ 1Mo 16,8"] },
      { number: 18, text: "Und er sagte zu ihm: Wir reisen von Bethlehem <in> Juda an das äußerste Ende des Gebirges Ephraim. Von dort bin ich her, und ich war nach Bethlehem <in> Juda gegangen, und ich gehe <nun> in mein Haus <zurück>*, aber es gibt keinen, der mich in <sein> Haus aufnimmt.", footnotes: ["T.; Mas. T.: und ich gehe mit dem Haus des HERRN"] },
      { number: 19, text: "Und wir haben sowohl Stroh als auch Futter für unsere Esel, und auch Brot und Wein habe ich für mich und für deine Magd und für den Diener, der bei deinen Knechten ist, <wir haben> keinen Mangel an irgendetwas." },
      { number: 20, text: "Da sagte der alte Mann: Friede <sei mit> dir*! Doch, wenn es dir an etwas fehlt, lass mich für dich sorgen*. Doch auf dem Platz übernachte nicht*!", footnotes: ["℘ Kap. 6,23; 1Mo 43,23", "w. Doch, dein Mangel sei auf mir", "℘ 1Mo 19,2.3; Hebr 13,2"] },
      { number: 21, text: "So führte er ihn in sein Haus und mischte <Futter> für die Esel. Und sie wuschen ihre Füße* und aßen und tranken.", footnotes: ["℘ 1Mo 18,4"] },
      { number: 22, text: "Als sie nun ihr Herz guter Dinge sein ließen, siehe, da umringten die Männer der Stadt, ruchlose Männer*, das Haus, trommelten gegen die Tür und sagten zu dem alten Mann, dem Herrn des Hauses: Führe den Mann, der in dein Haus gekommen ist, heraus, wir wollen ihn erkennen*!", footnotes: ["w. die Männer der Stadt, Männer, Söhne der Ruchlosigkeit", "℘ 1Mo 19,4.5; Hos 9,9"] },
      { number: 23, text: "Da ging der Mann, der Herr des Hauses, zu ihnen hinaus und sagte zu ihnen: Nicht doch, meine Brüder, tut doch nichts Übles! Nachdem dieser Mann in mein Haus gekommen ist, dürft ihr solch eine Schandtat nicht begehen*!", footnotes: ["℘ 1Mo 19,8; 34,7"] },
      { number: 24, text: "Siehe, meine Tochter, die <noch> Jungfrau <ist>, und seine Nebenfrau, sie will ich <euch> herausbringen. Ihnen tut Gewalt an und macht mit ihnen, was gut ist in euren Augen. Aber an diesem Mann dürft ihr so eine schwere Schandtat nicht begehen!" },
      { number: 25, text: "Aber die Männer wollten nicht auf ihn hören. Da ergriff der Mann seine Nebenfrau und führte sie zu ihnen hinaus auf die Straße. Und sie erkannten sie und trieben ihren Mutwillen mit ihr die ganze Nacht hindurch bis an den Morgen. Und sie ließen sie gehen, als die Morgenröte aufging." },
      { number: 26, text: "Und die Frau kam beim Anbruch des Morgens und fiel nieder am Eingang des Hauses des Mannes, wo ihr Herr war, <und lag dort,> bis es hell wurde." },
      { number: 27, text: "Und ihr Herr stand am Morgen auf, öffnete die Tür des Hauses und trat hinaus, um seines Weges zu gehen. Siehe, da lag die Frau, seine Nebenfrau, am Eingang des Hauses, ihre Hände auf der Schwelle." },
      { number: 28, text: "Da sagte er zu ihr: Steh auf und lass uns gehen! Aber niemand antwortete*. Da nahm er sie auf den Esel, und der Mann machte sich auf und zog an seinen Ort.", footnotes: ["℘ Kap. 20,5"] },
      { number: 29, text: "Und als er in sein Haus gekommen war, nahm er das Messer, ergriff seine Nebenfrau und zerlegte sie, Glied für Glied*, in zwölf Stücke und schickte sie ins ganze Gebiet Israels*.", footnotes: ["w. entsprechend ihren Gebeinen", "℘ Kap. 20,6; 1Sam 11,7"] },
      { number: 30, text: "Und es geschah, jeder, der es sah, sagte: <So etwas> wie das hier ist nicht geschehen, noch wurde es gesehen seit dem Tag, da die Söhne Israel aus dem Land Ägypten heraufgezogen sind, bis zu diesem Tag. Richtet euer Herz darauf*, beratet und redet*!", footnotes: ["so mit einigen hebr. Handschr. und der aram. Üs.; Mas. T.: Richtet euch darauf", "℘ Kap. 20,7; Spr 20,18"] },
    ]},
    { number: 20, verses: [
      { number: 1, text: "Und alle Söhne Israel zogen aus, und die Gemeinde — von Dan bis Beerscheba*, dazu das Land Gilead* — versammelte sich wie ein Mann vor dem HERRN* nach Mizpa*.", heading: "Krieg der übrigen Stämme gegen Benjamin", footnotes: ["℘ 1Sam 3,20; 2Sam 3,10; 1Kö 5,5; 1Chr 21,2; 2Chr 30,5", "℘ Jos 22,9", "℘ Jos 4,13", "℘ Kap. 11,34; Jos 18,26; 1Sam 11,7"] },
      { number: 2, text: "Und die Oberhäupter des ganzen Volkes traten zusammen, alle Stämme Israels, zur Versammlung des Volkes Gottes: 400 000 Mann zu Fuß, die das Schwert zogen*.", footnotes: ["℘ Jos 22,12"] },
      { number: 3, text: "Und die Söhne Benjamin hörten, dass die Söhne Israel nach Mizpa hinaufgezogen waren. Und die Söhne Israel sagten: Redet <doch>! Wie ist diese Übeltat geschehen*?", footnotes: ["℘ V. 12; 5Mo 13,15"] },
      { number: 4, text: "Da antwortete der levitische Mann, der Mann der ermordeten Frau, und sagte: Ich war nach Gibea gekommen, das zu Benjamin gehört, ich und meine Nebenfrau, um <dort> zu übernachten*.", footnotes: ["℘ Kap. 19,15"] },
      { number: 5, text: "Da erhoben sich die Bürger* von Gibea gegen mich und umringten meinetwegen* nachts das Haus*. Mich gedachten sie umzubringen, und meiner Nebenfrau taten sie Gewalt an, so dass sie starb*.", footnotes: ["w. die <Grund>besitzer, o. die Herren", "w. gegen mich", "℘ Kap. 19,22-29", "℘ 3Mo 18,24-30; Jos 7,15"] },
      { number: 6, text: "Da ergriff ich meine Nebenfrau, zerlegte sie in <Stücke> und schickte sie in das ganze Gebiet des Erbteils Israels*; denn sie haben ein Verbrechen und eine Schandtat begangen in Israel*.", footnotes: ["℘ 3Mo 18,24-30; Jos 7,15", "℘ 3Mo 18,24-30; Jos 7,15"] },
      { number: 7, text: "Siehe, nun seid ihr alle zusammen, Söhne Israel: So bildet euch hier eine Meinung und <schafft> Rat*!", footnotes: ["℘ Kap. 19,30"] },
      { number: 8, text: "Da stand das ganze Volk auf wie ein Mann und sagte: Wir wollen nicht gehen, jeder in sein Zelt, und nicht <vom Weg> abbiegen, jeder in sein Haus;" },
      { number: 9, text: "sondern dies ist die Sache, die wir jetzt an Gibea tun wollen: <Wir kommen> über es nach dem Los*!", footnotes: ["℘ Spr 16,33"] },
      { number: 10, text: "Wir nehmen <je> zehn Männer von hundert aus allen Stämmen Israels und hundert von tausend und tausend von zehntausend, dass sie Wegzehrung für das Volk holen, um bei ihrer Ankunft an Gibea*-Benjamin der ganzen Schandtat entsprechend zu handeln, die es in Israel begangen hat*.", footnotes: ["Mas. T.: Geba", "℘ 3Mo 18,24-30; Jos 7,15"] },
      { number: 11, text: "Und alle Männer von Israel versammelten sich gegen die Stadt, wie ein Mann verbündet." },
      { number: 12, text: "Und die Stämme Israels sandten Männer in den ganzen Stamm Benjamin* und <ließen> sagen: Was ist das für eine Untat, die unter euch geschehen ist*!", footnotes: ["so die alten Üs.; Mas. T.: in alle Stämme Benjamin", "℘ V. 3"] },
      { number: 13, text: "So gebt jetzt die Männer heraus, die Söhne der Ruchlosigkeit, die in Gibea sind, dass wir sie töten und das Böse aus Israel wegschaffen*! Aber die Söhne Benjamin wollten nicht auf die Stimme ihrer Brüder, der Söhne Israel, hören.", footnotes: ["℘ 5Mo 17,7.12"] },
      { number: 14, text: "Und die Söhne Benjamin versammelten sich aus den Städten nach Gibea, um zum Kampf mit den Söhnen Israel auszuziehen." },
      { number: 15, text: "Und an jenem Tag wurden die Söhne Benjamin aus den Städten gemustert: 26 000 Mann, die das Schwert zogen, abgesehen von den Bewohnern von Gibea; <auch> sie wurden gemustert: 700 auserlesene Männer." },
      { number: 16, text: "Unter diesem ganzen <Kriegs>volk waren 700 auserlesene Männer, die Linkshänder waren*. Diese alle schleuderten mit dem Stein aufs Haar <genau> und verfehlten <ihr Ziel> nie*.", footnotes: ["℘ Kap. 3,15", "℘ 1Chr 12,2"] },
      { number: 17, text: "Und die Männer von Israel wurden gemustert, abgesehen von Benjamin: 400 000 Mann, die das Schwert zogen; diese alle waren Kriegsmänner." },
      { number: 18, text: "Und sie machten sich auf und zogen hinauf nach Bethel und befragten Gott*. Und die Söhne Israel sagten: Wer von uns soll zuerst* hinaufziehen zum Kampf mit den Söhnen Benjamin? Und der HERR sprach: Juda zuerst!", footnotes: ["℘ Kap. 1,1; 1Sam 10,3", "℘ Kap. 1,2"] },
      { number: 19, text: "Und die Söhne Israel machten sich am Morgen auf und lagerten sich gegen Gibea." },
      { number: 20, text: "Und die Männer von Israel zogen aus zum Kampf mit Benjamin, und die Männer von Israel ordneten sich zur Schlacht gegen sie, zu Gibea." },
      { number: 21, text: "Und die Söhne Benjamin zogen aus Gibea heraus, und sie streckten unter Israel an jenem Tag 22 000 Mann zu Boden*.", footnotes: ["℘ 1Mo 49,27; Hos 10,9"] },
      { number: 22, text: "Aber das <Kriegs>volk fasste <neuen> Mut, die Männer von Israel, und sie ordneten sich nochmals zur Schlacht an der Stelle, wo sie sich am ersten Tag geordnet hatten." },
      { number: 23, text: "Die Söhne Israel waren nämlich hinaufgezogen und hatten vor dem HERRN geweint bis zum Abend*. Und sie hatten den HERRN befragt*: Soll ich nochmals ausrücken zum Kampf mit den Söhnen meines Bruders Benjamin? Und der HERR hatte gesagt: Zieht gegen ihn hinauf!", footnotes: ["℘ Kap. 21,2; Jos 7,6; 1Sam 7,6; 2Sam 3,35", "℘ Kap. 1,1; 1Sam 10,3"] },
      { number: 24, text: "Und die Söhne Israel näherten sich den Söhnen Benjamin am zweiten Tag." },
      { number: 25, text: "Und <auch> Benjamin zog am zweiten Tag aus Gibea heraus, ihnen entgegen, und sie streckten unter den Söhnen Israel nochmals 18 000 Mann zu Boden*; diese alle zogen das Schwert.", footnotes: ["℘ 1Mo 49,27; Hos 10,9"] },
      { number: 26, text: "Da zogen alle Söhne Israel und das ganze <Kriegs>volk hinauf und kamen nach Bethel*. Und sie weinten und saßen dort vor dem HERRN* und fasteten an jenem Tag bis zum Abend*; und sie opferten Brandopfer und Heilsopfer* vor dem HERRN*.", footnotes: ["℘ V. 18; 1Mo 28,19", "℘ Jos 24,1", "℘ Kap. 21,2; Jos 7,6; 1Sam 7,6; 2Sam 3,35", "o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "℘ Kap. 21,4"] },
      { number: 27, text: "Und die Söhne Israel befragten den HERRN* — denn die Lade des Bundes Gottes war in jenen Tagen dort*,", footnotes: ["℘ Kap. 1,1; 1Sam 10,3", "℘ 2Sam 7,6.7"] },
      { number: 28, text: "und Pinhas*, der Sohn Eleasars, des Sohnes Aarons, stand vor ihr* in jenen Tagen — und sie sagten: Soll ich noch einmal zum Kampf mit den Söhnen meines Bruders Benjamin ausziehen, oder soll ich aufhören? Da sprach der HERR: Zieht hinauf, denn morgen werde ich ihn in deine Hand geben*!", footnotes: ["℘ 2Mo 6,25", "d. h. übte den Priesterdienst aus", "℘ Kap. 1,2"] },
      { number: 29, text: "Und Israel legte <Leute in den> Hinterhalt ringsum gegen Gibea*.", footnotes: ["℘ Jos 8,2.4"] },
      { number: 30, text: "Und die Söhne Israel zogen am dritten Tag hinauf gegen die Söhne Benjamin und ordneten sich <zum Kampf> gegen Gibea wie die vorigen Male*.", footnotes: ["w. wie Mal für Mal"] },
      { number: 31, text: "Und <auch> die Söhne Benjamin zogen heraus, dem <Kriegs>volk entgegen, wurden von der Stadt abgeschnitten und fingen an, einige* vom <Kriegs>volk zu erschlagen* wie die vorigen Male* — auf den Straßen, von denen die eine nach Bethel hinaufsteigt und die andere nach Gibea —, im <offenen> Feld etwa dreißig Mann von Israel.", footnotes: ["w. Erschlagene", "℘ Jos 8,17", "w. wie Mal für Mal"] },
      { number: 32, text: "Da sagten die Söhne Benjamin: Sie sind vor uns geschlagen wie beim ersten <Mal>. Die Söhne Israel aber sagten: Lasst uns fliehen* und sie von der Stadt abziehen zu den Straßen hin!", footnotes: ["℘ Jos 8,6"] },
      { number: 33, text: "Da machten sich alle Männer von Israel von ihrer Stelle auf und ordneten sich <neu> bei Baal-Tamar, während der Hinterhalt Israels aus seiner Stellung hervorbrach, aus der Lichtung von Geba*.", footnotes: ["Manche nehmen als ursprünglichen Text an: westlich von Gibea"] },
      { number: 34, text: "Und es kamen gegenüber von Gibea zehntausend auserlesene Männer aus ganz Israel heran, und der Kampf war schwer. Jene aber erkannten nicht, dass das Unglück sie erreicht hatte*.", footnotes: ["℘ Jos 8,14-17"] },
      { number: 35, text: "Und der HERR schlug Benjamin vor Israel, und die Söhne Israel streckten unter Benjamin an jenem Tag 25 100 Mann nieder; diese alle zogen das Schwert." },
      { number: 36, text: "Da mussten die Söhne Benjamin sehen, dass sie geschlagen waren. Und die Männer von Israel gaben Benjamin Raum, weil sie sich auf den Hinterhalt verließen, den sie auf Gibea zu gelegt hatten." },
      { number: 37, text: "Und der Hinterhalt eilte herbei und überfiel Gibea. Und der Hinterhalt zog hin und schlug die ganze Stadt mit der Schärfe des Schwertes*.", footnotes: ["℘ Jos 8,14-17"] },
      { number: 38, text: "Die Männer von Israel hatten aber eine Verabredung mit dem Hinterhalt, eine dicke Rauchwolke aus der Stadt aufsteigen zu lassen." },
      { number: 39, text: "Als nun die Männer von Israel im Kampf kehrtmachten und Benjamin angefangen hatte, unter den Männern von Israel einige* zu erschlagen, etwa dreißig Mann, so dass sie sagten: Sie sind* ja vollständig vor uns geschlagen wie im vorigen Kampf! —", footnotes: ["w. Erschlagene", "w. Er ist; d. h. Israel"] },
      { number: 40, text: "da begann die Wolke aus der Stadt aufzusteigen als Rauchsäule. Und als Benjamin sich umwandte, siehe, da ging die ganze Stadt <in Flammen> auf zum Himmel*.", footnotes: ["℘ Jos 8,20"] },
      { number: 41, text: "Da machten die Männer von Israel <wieder> kehrt. Die Männer von Benjamin aber waren bestürzt, denn sie sahen, dass das Unglück sie erreicht hatte*.", footnotes: ["℘ Jos 8,20"] },
      { number: 42, text: "Und sie wandten sich <zur Flucht> vor den Männern von Israel auf den Weg zur Wüste; aber die Schlacht holte sie ein*. Und die, die aus den Städten <kamen>, streckten sie* in ihrer Mitte nieder.", footnotes: ["w. ihn; d. h. Benjamin", "w. ihn; d. h. Benjamin"] },
      { number: 43, text: "Sie umzingelten Benjamin, jagten ihm nach <ohne> Rast <und> holten es gegenüber von Gibea ein, gegen Sonnenaufgang." },
      { number: 44, text: "So fielen von Benjamin 18 000 Mann; diese alle waren tapfere Männer." },
      { number: 45, text: "Da wandten sie sich und flohen in die Wüste zum Felsen Rimmon*. Aber die Israeliten* hielten unter ihnen auf den Straßen eine Nachlese von fünftausend Mann und setzten ihnen nach bis Gidom und erschlugen von ihnen <nochmals> zweitausend Mann.", footnotes: ["℘ Kap. 21,13", "w. sie"] },
      { number: 46, text: "Und es war <die Zahl> aller Gefallenen Benjamins an jenem Tag 25 000 Mann, die das Schwert zogen; diese alle waren tapfere Männer." },
      { number: 47, text: "Sechshundert Mann aber wandten sich und flohen in die Wüste zum Felsen Rimmon* hin; und sie blieben am Felsen Rimmon vier Monate. —", footnotes: ["℘ Kap. 21,13"] },
      { number: 48, text: "Und die Männer von Israel kehrten zu den Söhnen Benjamin zurück und schlugen sie mit der Schärfe des Schwertes, *<alles> in der Stadt, <von den> Männern* bis zum Vieh, bis zu allem, was sich vorfand. Auch alle die Städte, die sich vorfanden, steckten sie in Brand*.", footnotes: ["so mit den meisten hebr. Handschr.; Mas. T.: von der Stadt <und zwar von ihrer> heilen Stelle", "so mit den meisten hebr. Handschr.; Mas. T.: von der Stadt <und zwar von ihrer> heilen Stelle", "℘ Kap. 21,23"] },
    ]},
    { number: 21, verses: [
      { number: 1, text: "Die Männer von Israel aber hatten in Mizpa geschworen: Niemand von uns darf seine Tochter <einem aus> Benjamin zur Frau geben!", heading: "Rettung eines Restes von Benjamin" },
      { number: 2, text: "Und das Volk kam nach Bethel, und sie saßen dort bis zum Abend vor Gott. Und sie erhoben ihre Stimme und brachen in ein großes Weinen aus*.", footnotes: ["℘ Kap. 20,23.26; 1Sam 30,4"] },
      { number: 3, text: "Und sie sagten: HERR, du Gott Israels, wozu ist dies in Israel geschehen, dass heute ein <ganzer> Stamm aus Israel fehlt?" },
      { number: 4, text: "Und es geschah am andern Tag, da machte sich das Volk früh auf, und sie bauten dort einen Altar* und opferten Brandopfer und Heilsopfer*.", footnotes: ["℘ Kap. 6,24", "o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer\n℘ Kap. 20,26; 2Sam 24,25"] },
      { number: 5, text: "Und die Söhne Israel sprachen: Wer ist es, der von allen Stämmen Israels nicht in die Versammlung zu dem HERRN heraufgekommen ist? Denn gegen den, der nicht zu dem HERRN nach Mizpa heraufkäme, war der große Schwur ergangen, der besagte: Getötet, getötet soll er werden*!", footnotes: ["℘ 1Sam 11,7; 14,24"] },
      { number: 6, text: "Und die Söhne Israel hatten Mitleid mit ihrem Bruder Benjamin, und sie sagten: Heute ist ein <ganzer> Stamm von Israel abgehauen worden!" },
      { number: 7, text: "Was sollen wir für sie, die Übriggebliebenen, tun, <um ihnen> zu Frauen <zu verhelfen>? Wir selbst haben ja bei dem HERRN geschworen, ihnen keine von unseren Töchtern zur Frau zu geben." },
      { number: 8, text: "Und sie sagten: Wer ist der eine von den Stämmen Israels, der nicht zu dem HERRN nach Mizpa heraufgekommen ist? Und siehe, da war niemand von Jabesch <in> Gilead* ins Lager, in die Versammlung, gekommen*.", footnotes: ["℘ 1Sam 11,1.9", "℘ Kap. 5,23"] },
      { number: 9, text: "Da wurde das Volk gemustert, und siehe, dort war niemand von den Bewohnern von Jabesch <in> Gilead." },
      { number: 10, text: "Da sandte die Gemeinde zwölftausend Mann von den tapferen Männern dorthin, und sie befahlen ihnen: Geht hin und schlagt die Bewohner von Jabesch <in> Gilead mit der Schärfe des Schwertes, samt den Frauen und Kindern!" },
      { number: 11, text: "Und das ist es, was ihr tun sollt: An jedem Mann sowie an jeder Frau, die das Beilager eines Mannes gekannt hat, sollt ihr den Bann vollstrecken*!", footnotes: ["℘ 4Mo 31,17.18"] },
      { number: 12, text: "Und sie fanden unter den Bewohnern von Jabesch <in> Gilead vierhundert Mädchen, Jungfrauen, von denen keine einen Mann im Beilager erkannt hatte; die brachten sie ins Lager nach Silo*, das im Land Kanaan <liegt>.", footnotes: ["℘ Jos 18,1"] },
      { number: 13, text: "Und die ganze Gemeinde sandte hin und redete zu den Söhnen Benjamin, die am Felsen Rimmon waren*, und rief ihnen zu: Friede!", footnotes: ["℘ Kap. 20,47"] },
      { number: 14, text: "So kehrte Benjamin in jener Zeit zurück. Und sie gaben ihnen die Frauen, die sie hatten leben lassen von den Frauen von Jabesch <in> Gilead; aber die reichten so nicht aus für sie." },
      { number: 15, text: "Und das Volk hatte Mitleid mit Benjamin, weil der HERR einen Riss gemacht hatte in den Stämmen Israels." },
      { number: 16, text: "Und die Ältesten der Gemeinde sagten: Was sollen wir für die Übriggebliebenen tun, <um ihnen> zu Frauen <zu verhelfen>? Denn die Frau ist aus Benjamin ausgerottet." },
      { number: 17, text: "Und sie sagten: Der Besitz der Entkommenen <muss> Benjamin <bleiben>, damit nicht ein Stamm aus Israel ausgelöscht wird." },
      { number: 18, text: "Wir aber, wir können ihnen keine Frauen von unseren Töchtern geben; denn die Söhne Israel haben geschworen: Verflucht sei, wer Benjamin eine Frau gibt!" },
      { number: 19, text: "Und sie sagten: Siehe, <da ist doch> ein Fest des HERRN von Jahr zu Jahr in Silo, das nördlich von Bethel <liegt>, gegen Sonnenaufgang von der Straße, die von Bethel nach Sichem hinaufführt, und südlich von Lebona." },
      { number: 20, text: "Und sie befahlen den Söhnen Benjamin: Geht hin und legt euch in den Weinbergen auf die Lauer!" },
      { number: 21, text: "Und wenn ihr <dann> seht, siehe, die Töchter von Silo ziehen heraus, um im Reigentanz zu tanzen*, dann kommt hervor aus den Weinbergen und fangt euch unter den Töchtern von Silo jeder seine Frau und zieht <wieder> hin ins Land Benjamin!", footnotes: ["℘ Kap. 11,34"] },
      { number: 22, text: "Und es soll geschehen, wenn ihre Väter oder ihre Brüder kommen, um uns Vorwürfe zu machen, wollen wir zu ihnen sagen: Seid barmherzig mit ihnen! <Sie haben zu uns gesagt:> Keiner von uns hat im Krieg <gegen Jabesch> seine Frau bekommen. — Ihr habt sie ihnen ja nicht selbst gegeben, dass ihr jetzt schuldig wäret." },
      { number: 23, text: "Da machten es die Söhne Benjamin so und nahmen sich Frauen nach ihrer Zahl von den Tanzenden, die sie raubten. Und sie zogen fort und kehrten in ihr Erbteil zurück. Und sie bauten die Städte <wieder> auf und wohnten in ihnen*.", footnotes: ["℘ Kap. 20,48"] },
      { number: 24, text: "Und die Söhne Israel gingen davon in jener Zeit, jeder zu seinem Stamm und zu seiner Sippe. So zogen sie von dort weg, jeder in sein Erbteil." },
      { number: 25, text: "In jenen Tagen war kein König in Israel. Jeder tat, was recht war in seinen Augen.*", footnotes: ["℘ Kap. 17,6; Jes 53,6; 66,3; Röm 3,12"] },
    ]},
  ]
};
